window.__OPENSTAX_PHYSICS__[2] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:44:27.200Z","number":2,"code":"ch02","slug":"motion-in-one-dimension","title":"Motion in One Dimension","titleVi":"Chuyển Động Thẳng 1 Chiều (Motion in One Dimension)","sections":[{"uid":"hsphys.ch02.sec00","moduleId":"m54097","number":"2.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch02.sec00.sub01","title":"Chapter Introduction","summaryVi":"Mở đầu Chương 2: Khám phá Động học 1 chiều (1D Kinematics) — cách mô tả chuyển động thẳng bằng hệ quy chiếu, độ dịch chuyển, vận tốc và đồ thị.","paragraphs":["Outside of an airplane, have you ever traveled faster than 150 mph? Can you imagine traveling in a train like the one shown in Figure 2.0 that goes close to 300 mph? Despite the high speed, the people riding in this train may not notice that they are moving at all unless they look out the window! This is because motion, even motion at 300 mph, is relative to the observer.","In this chapter, you will learn why it is important to identify a reference frame in order to clearly describe motion. For now, the motion you describe will be one-dimensional. Within this context, you will learn the difference between distance and displacement as well as the difference between speed and velocity. Then you will look at some graphing and problem-solving techniques."],"figures":[{"sourceId":"fs-id1167067196700","filename":"CNX_HSPhysics_02_00_train.jpg","relativePath":"media/CNX_HSPhysics_02_00_train.jpg","alt":"A photograph shows a maglev train traveling past an airport."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch02.sec01","moduleId":"m54108","number":"2.1","slug":"relative-motion-distance-and-displacement","title":"Relative Motion, Distance, and Displacement","isIntroduction":false,"learningObjectives":["Describe motion in different reference frames","Define distance and displacement, and distinguish between the two","Solve problems involving distance and displacement"],"bilingualGuide":{"notebookSummaryVi":"Chuyển động tương đối (Relative Motion), Hệ quy chiếu (Reference Frame) và phân biệt sắc nét Quãng đường (Distance — vô hướng) với Độ dịch chuyển (Displacement Δd = d_f - d_0 — đại lượng vectơ).","wordProblemCues":[{"phraseEn":"displacement Δd = d_f - d_0","meaningVi":"Độ dịch chuyển = Vị trí cuối trừ Vị trí đầu (có dấu!)","mathNotation":"Δd = d_f - d_0"},{"phraseEn":"magnitude of displacement","meaningVi":"Độ lớn của độ dịch chuyển (giá trị tuyệt đối |Δd|)","mathNotation":"|Δd|"}],"commonTrapsVi":["⚠️ False Friend kinh điển Vật Lý 10 (GDPT 2018): Distance = Quãng đường (luôn dương), Displacement = Độ dịch chuyển (có thể âm hoặc bằng 0). Luôn đọc kỹ chiều dương (positive direction) đề bài quy ước!"]},"keyEquations":[{"name":"Displacement","formula":"\\(\\Delta \\mathbf{d} = {\\mathbf{d}}_{f} - {\\mathbf{d}}_{0}\\)"}],"subsections":[{"uid":"hsphys.ch02.sec01.sub01","title":"Defining Motion","summaryVi":"Phân tích 3 khái niệm nền tảng nhất của Cơ học: Hệ quy chiếu (Reference Frame), Quãng đường (Distance — tổng chiều dài đường đi, luôn dương) và Độ dịch chuyển (Displacement Δd = d_f - d_0 — mũi tên vectơ từ điểm đầu đến điểm cuối, có dấu +/−).","paragraphs":["Our study of physics opens with kinematics —the study of motion without considering its causes. Objects are in motion everywhere you look. Everything from a tennis game to a space-probe flyby of the planet Neptune involves motion. When you are resting, your heart moves blood through your veins. Even in inanimate objects, atoms are always moving.","How do you know something is moving? The location of an object at any particular time is its position . More precisely, you need to specify its position relative to a convenient reference frame . Earth is often used as a reference frame, and we often describe the position of an object as it relates to stationary objects in that reference frame. For example, a rocket launch would be described in terms of the position of the rocket with respect to Earth as a whole, while a professor’s position could be described in terms of where she is in relation to the nearby white board. In other cases, we use reference frames that are not stationary but are in motion relative to Earth. To describe the position of a person in an airplane, for example, we use the airplane, not Earth, as the reference frame. (See Figure 2.1.) Thus, you can only know how fast and in what direction an object's position is changing against a background of something else that is either not moving or moving with a known speed and direction. The reference frame is the coordinate system from which the positions of objects are described.","Your classroom can be used as a reference frame. In the classroom, the walls are not moving. Your motion as you walk to the door, can be measured against the stationary background of the classroom walls. You can also tell if other things in the classroom are moving, such as your classmates entering the classroom or a book falling off a desk. You can also tell in what direction something is moving in the classroom. You might say, “The teacher is moving toward the door.” Your reference frame allows you to determine not only that something is moving but also the direction of motion.","You could also serve as a reference frame for others’ movement. If you remained seated as your classmates left the room, you would measure their movement away from your stationary location. If you and your classmates left the room together, then your perspective of their motion would be change. You, as the reference frame, would be moving in the same direction as your other moving classmates. As you will learn in the Snap Lab , your description of motion can be quite different when viewed from different reference frames.","As we study the motion of objects, we must first be able to describe the object’s position. Before your parent drives you to school, the car is sitting in your driveway. Your driveway is the starting position for the car. When you reach your high school, the car has changed position. Its new position is your school.","Physicists use variables to represent terms. We will use d to represent car’s position. We will use a subscript to differentiate between the initial position, d 0 , and the final position, d f . In addition, vectors, which we will discuss later, will be in bold or will have an arrow above the variable. Scalars will be italicized.","Now imagine driving from your house to a friend's house located several kilometers away. How far would you drive? The distance an object moves is the length of the path between its initial position and its final position. The distance you drive to your friend's house depends on your path. As shown in Figure 2.1, distance is different from the length of a straight line between two points. The distance you drive to your friend's house is probably longer than the straight line between the two houses.","We often want to be more precise when we talk about position. The description of an object’s motion often includes more than just the distance it moves. For instance, if it is a five kilometer drive to school, the distance traveled is 5 kilometers. After dropping you off at school and driving back home, your parent will have traveled a total distance of 10 kilometers. The car and your parent will end up in the same starting position in space. The net change in position of an object is its displacement , or Δ d . The Greek letter delta, \\(\\Delta\\), means change in .","If you are describing only your drive to school and the route is a straight line, then the distance traveled and the displacement are the same—5 kilometers. When you are describing the entire round trip, distance and displacement are different. When you describe distance, you only include the magnitude , the size or amount, of the distance traveled. However, when you describe the displacement, you take into account both the magnitude of the change in position and the direction of movement.","In our previous example, the car travels a total of 10 kilometers, but it drives five of those kilometers forward toward school and five of those kilometers back in the opposite direction. If we ascribe the forward direction a positive (+) and the opposite direction a negative (–), then the two quantities will cancel each other out when added together.","A quantity, such as distance, that has magnitude (i.e., how big or how much) and sometimes a sign (e.g., electric charge, temperature in Celsius, or component of a vector) but does not take into account direction is called a scalar . A quantity, such as displacement, that has both magnitude and direction is called a vector . A vector with magnitude zero is a special case of a vector that has no direction.","Hopefully you now understand the conceptual difference between distance and displacement. Understanding concepts is half the battle in physics. The other half is math. A stumbling block to new physics students is trying to wade through the math of physics while also trying to understand the associated concepts. This struggle may lead to misconceptions and answers that make no sense. Once the concept is mastered, the math is far less confusing.","So let’s review and see if we can make sense of displacement in terms of numbers and equations. You can calculate an object's displacement by subtracting its original position, d 0 , from its final position d f . In math terms that means","If the final position is the same as the initial position, then \\(\\Delta \\mathbf{d} = 0\\) .","To assign numbers and/or direction to these quantities, we need to define an axis with a positive and a negative direction. We also need to define an origin, or O . In Figure 2.1, the axis is in a straight line with home at zero and school in the positive direction. If we left home and drove the opposite way from school, motion would have been in the negative direction. We would have assigned it a negative value. In the round-trip drive, d f and d 0 were both at zero kilometers. In the one way trip to school, d f was at 5 kilometers and d 0 was at zero km. So, \\(\\Delta \\mathbf{d}\\) was 5 kilometers."],"figures":[{"sourceId":"fs-id1167067234812","filename":"CNX_HSPhysics_02_01_airplane.jpg","relativePath":"media/CNX_HSPhysics_02_01_airplane.jpg","alt":"A photograph of an airplane flying in an upward direction is shown. The sky is partly cloudy."},{"sourceId":"fs-id1167067054121","filename":"CNX_HSPhysics_02_01_house.jpg","relativePath":"media/CNX_HSPhysics_02_01_house.jpg","alt":"A drawing is shown of a house on the left facing a school on the right. A vector between points from the house to the school is labeled d o on the left and d f on the right. A car is shown driving from the house to the school."},{"sourceId":"fs-id1167067090273","filename":"CNX_HSPhysics_02_01_comic.jpg","relativePath":"media/CNX_HSPhysics_02_01_comic.jpg","alt":"A diagram is shown of a house on the left labeled home and another house on the right labeled Friend's house. The driveways of the houses are facing each other and a curvy road connects the driveways. A car is on the curvy road about half-way between the two houses."},{"sourceId":"fs-id1167066807291","filename":"CNX_HSPhysics_02_01_arrow.jpg","relativePath":"media/CNX_HSPhysics_02_01_arrow.jpg","alt":"A drawing is shown of a house on the left facing a school on the right. The distance between the two is labeled five miles. A double-arrow vector between the house and the school is labeled do on the left and df on the right. The equation change in d total equals zero is shown below the vector."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch02.sec01.ex01","number":"2.1.1","title":"Calculating Distance and Displacement","problem":"A cyclist rides 3 km west and then turns around and rides 2 km east. (a) What is her displacement? (b) What distance does she ride? (c) What is the magnitude of her displacement?","problemImages":[{"sourceId":"fs-id1167066868872","filename":"CNX_HSPhysics_02_01_direction_img.jpg","relativePath":"media/CNX_HSPhysics_02_01_direction_img.jpg","alt":"A segment is shown, divided into two sections. The first section is labeled change in d two equals plus twelve kilometers and has a right pointing arrow, ending at a label df. The second section is labeled do at the end of it. A left-pointing arrow is above the entire segment and is labeled change in d one equals negative three kilometers. The right of the segment, a left-pointing arrow is shown with a W and a negative sign on the left side and E and a positive sign on the right side. The label do is in the center."}],"strategy":"To solve this problem, we need to find the difference between the final position and the initial position while taking care to note the direction on the axis. The final position is the sum of the two displacements, \\(\\Delta {\\mathbf{d}}_{1}\\) and \\(\\Delta {\\mathbf{d}}_{2}\\) .","solution":"Displacement: The rider’s displacement is Δ\nd =\nd\nf\n-\nd\n0\n= - 1  km .\nDistance: The distance traveled is 3 km + 2 km = 5 km.\nThe magnitude of the displacement is 1 km.","solutionImages":[],"solutionTables":[],"discussion":"The displacement is negative because we chose east to be positive and west to be negative. We could also have described the displacement as 1 km west. When calculating displacement, the direction mattered, but when calculating distance, the direction did not matter. The problem would work the same way if the problem were in the north–south or y -direction.\nPhysicists like to use standard units so it is easier to compare notes. The standard units for calculations are called SI units (International System of Units). SI units are based on the metric system. The SI unit for displacement is the meter (m), but sometimes you will see a problem with kilometers, miles, feet, or other units of length. If one unit in a problem is an SI unit and another is not, you will need to convert all of your quantities to the same system before you can carry out the calculation."}],"snapLabs":[{"uid":"hsphys.ch02.sec01.lab01","title":"Looking at Motion from Two Reference Frames","text":"In this activity you will look at motion from two reference frames. Which reference frame is correct?\nChoose an open location with lots of space to spread out so there is less chance of tripping or falling due to a collision and/or loose basketballs.\n1 basketball\nProcedure\nWork with a partner. Stand a couple of meters away from your partner. Have your partner turn to the side so that you are looking at your partner’s profile. Have your partner begin bouncing the basketball while standing in place. Describe the motion of the ball.\nNext, have your partner again bounce the ball, but this time your partner should walk forward with the bouncing ball. You will remain stationary. Describe the ball's motion.\nAgain have your partner walk forward with the bouncing ball. This time, you should move alongside your partner while continuing to view your partner’s profile. Describe the ball's motion.\nSwitch places with your partner, and repeat Steps 1–3.","images":[]},{"uid":"hsphys.ch02.sec01.lab02","title":"Distance vs. Displacement","text":"In this activity you will compare distance and displacement. Which term is more useful when making measurements?\n1 recorded song available on a portable device\n1 tape measure\n3 pieces of masking tape\nA room (like a gym) with a wall that is large and clear enough for all pairs of students to walk back and forth without running into each other.\nProcedure\nOne student from each pair should stand with their back to the longest wall in the classroom. Students should stand at least 0.5 meters away from each other. Mark this starting point with a piece of masking tape.\nThe second student from each pair should stand facing their partner, about two to three meters away. Mark this point with a second piece of masking tape.\nStudent pairs line up at the starting point along the wall.\nThe teacher turns on the music. Each pair walks back and forth from the wall to the second marked point until the music stops playing. Keep count of the number of times you walk across the floor.\nWhen the music stops, mark your ending position with the third piece of masking tape.\nMeasure from your starting, initial position to your ending, final position.\nMeasure the length of your path from the starting position to the second marked position. Multiply this measurement by the total number of times you walked across the floor. Then add this number to your measurement from step 6.\nCompare the two measurements from steps 6 and 7.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch02.sec01.feat01","type":"physics-in-action","title":"History: Galileo's Ship","text":"Galileo Galilei (1564–1642) studied motion and developed the concept of a reference frame. (Domenico Tintoretto)\nThe idea that a description of motion depends on the reference frame of the observer has been known for hundreds of years. The 17 th -century astronomer Galileo Galilei (Figure 2.1) was one of the first scientists to explore this idea. Galileo suggested the following thought experiment: Imagine a windowless ship moving at a constant speed and direction along a perfectly calm sea. Is there a way that a person inside the ship can determine whether the ship is moving? You can extend this thought experiment by also imagining a person standing on the shore. How can a person on the shore determine whether the ship is moving?\nGalileo came to an amazing conclusion. Only by looking at each other can a person in the ship or a person on shore describe the motion of one relative to the other. In addition, their descriptions of motion would be symmetric or opposite. A person inside the ship would describe the person on the land as moving past the ship. The person on shore would describe the ship and the person inside it as moving past. Galileo realized that observers moving at a constant speed and direction relative to each other describe motion in the same way. Galileo had discovered that a description of motion is only meaningful if you specify a reference frame.","images":[{"sourceId":"fs-id1167063419529","filename":"CNX_HSPhysics_02_01_Galileo.jpg","relativePath":"media/CNX_HSPhysics_02_01_Galileo.jpg","alt":"A painting of Galileo Galilei is shown."}]},{"uid":"hsphys.ch02.sec01.feat02","type":"tip","title":"Tips for Success","text":"In some books, x or s is used instead of d to describe position. In d 0 , said d naught , the subscript 0 stands for initial . When we begin to talk about two-dimensional motion, sometimes other subscripts will be used to describe horizontal position, d x , or vertical position, d y . So, you might see references to d 0x and d fy .","images":[]},{"uid":"hsphys.ch02.sec01.feat03","type":"tip","title":"Tips for Success","text":"You may place your origin wherever you would like. You have to make sure that you calculate all distances consistently from your zero and you define one direction as positive and the other as negative. Therefore, it makes sense to choose the easiest axis, direction, and zero. In the example above, we took home to be zero because it allowed us to avoid having to interpret a solution with a negative sign.","images":[]},{"uid":"hsphys.ch02.sec01.feat04","type":"tip","title":"Tips for Success","text":"Physicists like to use standard units so it is easier to compare notes. The standard units for calculations are called SI units (International System of Units). SI units are based on the metric system. The SI unit for displacement is the meter (m), but sometimes you will see a problem with kilometers, miles, feet, or other units of length. If one unit in a problem is an SI unit and another is not, you will need to convert all of your quantities to the same system before you can carry out the calculation.","images":[]},{"uid":"hsphys.ch02.sec01.feat05","type":"physics-in-action","title":"Mars Probe Explosion","text":"The Mars Climate Orbiter disaster illustrates the importance of using the correct calculations in physics. (NASA) Physicists make calculations all the time, but they do not always get the right answers. In 1998, NASA, the National Aeronautics and Space Administration, launched the Mars Climate Orbiter, shown in Figure 2.1, a $125-million-dollar satellite designed to monitor the Martian atmosphere. It was supposed to orbit the planet and take readings from a safe distance. The American scientists made calculations in English units (feet, inches, pounds, etc.) and forgot to convert their answers to the standard metric SI units. This was a very costly mistake. Instead of orbiting the planet as planned, the Mars Climate Orbiter ended up flying into the Martian atmosphere. The probe disintegrated. It was one of the biggest embarrassments in NASA’s history.","images":[{"sourceId":"fs-id1167066870524","filename":"CNX_HSPhysics_02_01_Mars.jpg","relativePath":"media/CNX_HSPhysics_02_01_Mars.jpg","alt":"An image of the Mars Climate Orbiter is shown hovering above Mars."}]}],"summaryPoints":["A description of motion depends on the reference frame from which it is described.","The distance an object moves is the length of the path along which it moves.","Displacement is the difference in the initial and final positions of an object."],"glossary":[{"term":"displacement","termVi":"Độ dịch chuyển (Δd)","ipa":"/dɪˈspleɪs.mənt/","definition":"the change in position of an object against a fixed axis","definitionVi":"Sự thay đổi vị trí của vật từ điểm đầu đến điểm cuối: Δd = d_f - d_0 (đại lượng vectơ — có hướng và có thể âm, dương hoặc bằng 0).","memoryTipVi":"Đi 1 vòng tròn về đúng chỗ cũ → Quãng đường > 0 nhưng Độ dịch chuyển = 0!"},{"term":"distance","termVi":"Quãng đường đi được (s)","ipa":"/ˈdɪs.təns/","definition":"the length of the path actually traveled between an initial and a final position","definitionVi":"Tổng độ dài quỹ đạo mà vật đi qua (đại lượng vô hướng — luôn không âm).","memoryTipVi":"⚠️ False Friend: Distance là QUÃNG ĐƯỜNG (vô hướng, không có dấu âm), khác hoàn toàn Displacement!"},{"term":"kinematics","termVi":"Động học","ipa":"/ˌkɪn.əˈmæt.ɪks/","definition":"the study of motion without considering its causes","definitionVi":"Phân ngành của Cơ học mô tả chuyển động của vật (vị trí, vận tốc, gia tốc) mà chưa xét đến lực gây ra chuyển động.","memoryTipVi":"Gốc Hy Lạp 'kinema' = chuyển động (cùng gốc với từ 'cinema' — điện ảnh!)."},{"term":"magnitude","termVi":"Độ lớn (của đại lượng vectơ)","ipa":"/ˈmæɡ.nɪ.tjuːd/","definition":"size or amount","definitionVi":"Giá trị số không âm biểu diễn kích thước của một đại lượng vectơ (bỏ qua dấu/hướng).","memoryTipVi":"Ví dụ: Độ dịch chuyển là -15 m → Độ lớn (Magnitude) là |-15 m| = 15 m."},{"term":"position","termVi":"Vị trí / Tọa độ (d)","ipa":"/pəˈzɪʃ.ən/","definition":"the location of an object at any particular time","definitionVi":"Tọa độ xác định nơi ở của vật so với gốc tọa độ trong hệ quy chiếu đã chọn.","memoryTipVi":"Vị trí d₀ (initial position) và d_f (final position) quyết định độ dịch chuyển Δd."},{"term":"reference frame","termVi":"Hệ quy chiếu","ipa":"/ˈref.ər.əns freɪm/","definition":"a coordinate system from which the positions of objects are described","definitionVi":"Hệ tọa độ gắn với vật làm mốc (kèm đồng hồ đo thời gian) để quan sát và mô tả chuyển động.","memoryTipVi":"Chuyển động có tính tương đối: ngồi trên tàu hỏa thấy bạn bên cạnh đứng yên, nhưng người dưới sân ga thấy cả hai đang lao đi!"},{"term":"scalar","termVi":"Đại lượng vô hướng","ipa":"/ˈskeɪ.lər/","definition":"a quantity that has magnitude (and possibly sign) but no direction","definitionVi":"Đại lượng chỉ có độ lớn, không có hướng (quãng đường, tốc độ, thời gian, khối lượng, nhiệt độ).","memoryTipVi":"Scalar chỉ cần Con số + Đơn vị."},{"term":"vector","termVi":"Đại lượng vectơ","ipa":"/ˈvek.tər/","definition":"a quantity that has both magnitude and direction","definitionVi":"Đại lượng có cả ĐỘ LỚN và HƯỚNG (độ dịch chuyển, vận tốc, gia tốc, lực).","memoryTipVi":"Trong sách OpenStax Physics, ký hiệu vectơ được in đậm (d, v, a, F)."}],"assessments":[{"uid":"hsphys.ch02.sec01.q001","sourceId":"fs-id1167063790450","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What does it mean when motion is described as relative?","images":[],"choices":[{"label":"a","text":"It means that motion of any object is described relative to the motion of Earth."},{"label":"b","text":"It means that motion of any object is described relative to the motion of any other object."},{"label":"c","text":"It means that motion is independent of the frame of reference."},{"label":"d","text":"It means that motion depends on the frame of reference selected."}],"hasOfficialSolution":true,"solution":null,"correctChoice":"d","explanationVi":"Chuyển động có tính tương đối (relative): trạng thái chuyển động của một vật hoàn toàn phụ thuộc vào hệ quy chiếu (reference frame) bạn chọn và sẽ trông khác nhau trong các hệ quy chiếu khác nhau."},{"uid":"hsphys.ch02.sec01.q006","sourceId":"fs-id1167067025012","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"On an axis in which moving from right to left is positive, what is the displacement and distance of a student who walks 32 m to the right and then 17 m to the left?","images":[],"choices":[{"label":"a","text":"Displacement is -15 m and distance is -49 m ."},{"label":"b","text":"Displacement is -15 m and distance is 49 m."},{"label":"c","text":"Displacement is 15 m and distance is -49 m."},{"label":"d","text":"Displacement is 15 m and distance is 49 m."}],"hasOfficialSolution":true,"solution":null,"correctChoice":"b","explanationVi":"Đề quy ước sang TRÁI là chiều DƯƠNG (+). Đi sang phải 32 m là -32 m, rồi đi sang trái 17 m là +17 m → Độ dịch chuyển Δd = -32 + 17 = -15 m. Quãng đường luôn dương: 32 + 17 = 49 m! (Đáp án B)."},{"uid":"hsphys.ch02.sec01.q007","sourceId":"fs-id1167067109948","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Tiana jogs 1.5 km along a straight path and then turns and jogs 2.4 km in the opposite direction. She then turns back and jogs 0.7 km in the original direction. Let Tianas original direction be the positive direction. What are the displacement and distance she jogged?","images":[],"choices":[{"label":"a","text":"Displacement is 4.6 km,and distance is -0.2 km."},{"label":"b","text":"Displacement is -0.2 km, and distance is 4.6 km."},{"label":"c","text":"Displacement is 4.6 km, and distance is +0.2 km."},{"label":"d","text":"Displacement is +0.2 km, and distance is 4.6 km."}],"hasOfficialSolution":true,"solution":null,"correctChoice":"b","explanationVi":"Chiều ban đầu là chiều dương (+): Δd = +1.5 - 2.4 + 0.7 = -0.2 km. Quãng đường luôn dương: 1.5 + 2.4 + 0.7 = 4.6 km! (Đáp án B)."},{"uid":"hsphys.ch02.sec01.q010","sourceId":"eip-id1166851321481","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"In which example would you be correct in describing an object in motion while your friend would also be correct in describing that same object as being at rest?","images":[],"choices":[{"label":"a","text":"You are driving a car toward the east and your friend drives past you in the opposite direction with the same speed. In your frame of reference, you will be in motion. In your friends frame of reference, you will be at rest."},{"label":"b","text":"You are driving a car toward the east and your friend is standing at the bus stop. In your frame of reference, you will be in motion. In your friends frame of reference, you will be at rest."},{"label":"c","text":"You are driving a car toward the east and your friend is standing at the bus stop. In your frame of reference, your friend will be moving toward the west. In your friends frame of reference, he will be at rest."},{"label":"d","text":"You are driving a car toward the east and your friend is standing at the bus stop. In your frame of reference, your friend will be moving toward the east. In your friends frame of reference, he will be at rest."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec01.q014","sourceId":"fs-id1167067025012","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"On an axis in which moving from right to left is positive, what is the displacement and distance of a student who walks 32 m to the right and then 17 m to the left?","images":[],"choices":[{"label":"a","text":"Displacement is -15 m and distance is -49 m ."},{"label":"b","text":"Displacement is -15 m and distance is 49 m."},{"label":"c","text":"Displacement is 15 m and distance is -49 m."},{"label":"d","text":"Displacement is 15 m and distance is 49 m."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec01.q015","sourceId":"fs-id1167067109948","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Tiana jogs 1.5 km along a straight path and then turns and jogs 2.4 km in the opposite direction. She then turns back and jogs 0.7 km in the original direction. Let Tianas original direction be the positive direction. What are the displacement and distance she jogged?","images":[],"choices":[{"label":"a","text":"Displacement is 4.6 km,and distance is -0.2 km."},{"label":"b","text":"Displacement is -0.2 km, and distance is 4.6 km."},{"label":"c","text":"Displacement is 4.6 km, and distance is +0.2 km."},{"label":"d","text":"Displacement is +0.2 km, and distance is 4.6 km."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec01.q018","sourceId":"fs-id1167067158435","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Billy drops a ball from a height of 1 m. The ball bounces back to a height of 0.8 m, then bounces again to a height of 0.5 m, and bounces once more to a height of 0.2 m. Up is the positive direction. What are the total displacement of the ball and the total distance traveled by the ball?","images":[],"choices":[{"label":"a","text":"The displacement is equal to –4 m and the distance is equal to 4 m."},{"label":"b","text":"The displacement is equal to –1 m and the distance is equal to 1 m"},{"label":"c","text":"The displacement is equal to 4 m and the distance is equal to 1 m."},{"label":"d","text":"The displacement is equal to –1 m and the distance is equal to 4 m."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec01.q023","sourceId":"eip-id1166851210410","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If a space shuttle orbits Earth once, what is the shuttles distance traveled and displacement?","images":[],"choices":[{"label":"a","text":"Distance and displacement both are zero."},{"label":"b","text":"Distance is circumference of the circular orbit while displacement is zero."},{"label":"c","text":"Distance is zero while the displacement is circumference of the circular orbit."},{"label":"d","text":"Distance and displacement both are equal to circumference of the circular orbit."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec01.q024","sourceId":"fs-id1167066875649","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"While standing on a sidewalk facing the road, you see a bicyclist passing by toward your right. In the reference frame of the bicyclist, in which direction are you moving?","images":[],"choices":[{"label":"a","text":"in the same direction of motion as the bicyclist"},{"label":"b","text":"in the direction opposite the motion of the bicyclist"},{"label":"c","text":"stationary with respect to the bicyclist"},{"label":"d","text":"in the direction of velocity of the bicyclist"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec01.q027","sourceId":"fs-id1167067011687","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Find the distance traveled from the starting point for each path.\nWhich path has the maximum distance?","images":[{"sourceId":"fs-id1164565114161","filename":"CNX_HSPhysics_02_01_displace_img.jpg","relativePath":"media/CNX_HSPhysics_02_01_displace_img.jpg","alt":"A line begins at 0 and extends to the right. 2, 4, 6, 8, 10, and 12 are marked on the line, and it is titled displacement x (m). a green line A extends from 0 to the right. A red line c extends from two to the right, and makes an ess pattern at 10 where it goes back to 8, then reverses direction again and extends to infinity. An orange line D extends from 9 to the left, then reverses direction at 3. A purple line B extends from 12 to the left."}],"choices":[{"label":"a","text":"The distance for Path A is 6 m, Path B is 4 m, Path C is 12 m and for Path D is 7 m. The net displacement for Path A is 7 m, Path B is –4m, Path C is 8 m and for Path D is –5m. Path C has maximum distance and it is equal to 12 meters."},{"label":"b","text":"The distance for Path A is 6 m, Path B is 4 m, Path C is 8 m and for Path D is 7 m. The net displacement for Path A is 6 m, Path B is –4m, Path C is 12 m and for Path D is –5 m. Path A has maximum distance and it is equal to 6 meters."},{"label":"c","text":"The distance for Path A is 6 m, Path B is 4 m, Path C is 12 m and for Path D is 7 m. The net displacement for Path A is 6 m, Path B is –4 m, Path C is 8 m and for Path D is –5 m. Path C has maximum distance and it is equal to 12 meters."},{"label":"d","text":"The distance for Path A is 6 m, Path B is –4 m, Path C is 12 m and for Path D is –5 m. The net displacement for Path A is 7 m, Path B is 4 m, Path C is 8 m and for Path D is 7 m. Path A has maximum distance and it is equal to 6 m."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":1,"subsectionCount":1,"workedExampleCount":1,"snapLabCount":2,"glossaryCount":8,"assessmentCount":10}},{"uid":"hsphys.ch02.sec02","moduleId":"m54104","number":"2.2","slug":"speed-and-velocity","title":"Speed and Velocity","isIntroduction":false,"learningObjectives":["Calculate the average speed of an object","Relate displacement and average velocity"],"bilingualGuide":{"notebookSummaryVi":"Phân biệt Tốc độ (Speed = Distance / Time) và Vận tốc (Velocity = Displacement / Time). Phân biệt vận tốc trung bình với vận tốc tức thời.","wordProblemCues":[{"phraseEn":"average velocity","meaningVi":"Vận tốc trung bình (độ dịch chuyển / thời gian)","mathNotation":"v_avg = Δd / Δt"},{"phraseEn":"average speed","meaningVi":"Tốc độ trung bình (tổng quãng đường / tổng thời gian)","mathNotation":"s / t"}],"commonTrapsVi":["⚠️ False Friend: Chạy hết 1 vòng sân 400 m trong 50 s rồi về đúng vạch xuất phát → Tốc độ trung bình = 8 m/s, nhưng Vận tốc trung bình = 0 m/s!"]},"keyEquations":[{"name":"Average speed","formula":"\\({v}_{\\text{avg}} = \\frac{\\text{distance}}{\\text{time}}\\)"},{"name":"Average velocity","formula":"\\({\\mathbf{v}}_{\\text{avg}} = \\frac{\\Delta \\mathbf{d}}{\\Delta t} = \\frac{{\\mathbf{d}}_{\\text{f}} - {\\mathbf{d}}_{0}}{{t}_{\\text{f}} - {t}_{0}}\\)"}],"subsections":[{"uid":"hsphys.ch02.sec02.sub01","title":"Speed","summaryVi":"Tốc độ (Speed) là đại lượng vô hướng bằng Quãng đường chia Thời gian. Đồng hồ xe máy chỉ Tốc độ tức thời (Instantaneous Speed), còn lấy tổng quãng đường chia tổng thời gian ra Tốc độ trung bình (Average Speed).","paragraphs":["There is more to motion than distance and displacement. Questions such as, “How long does a foot race take?” and “What was the runner’s speed?” cannot be answered without an understanding of other concepts. In this section we will look at time , speed, and velocity to expand our understanding of motion.","A description of how fast or slow an object moves is its speed. Speed is the rate at which an object changes its location. Like distance, speed is a scalar because it has a magnitude but not a direction. Because speed is a rate, it depends on the time interval of motion. You can calculate the elapsed time or the change in time, \\(\\Delta t\\), of motion as the difference between the ending time and the beginning time","The SI unit of time is the second (s), and the SI unit of speed is meters per second (m/s), but sometimes kilometers per hour (km/h), miles per hour (mph) or other units of speed are used.","When you describe an object's speed, you often describe the average over a time period. Average speed , v avg , is the distance traveled divided by the time during which the motion occurs.","You can, of course, rearrange the equation to solve for either distance or time","Suppose, for example, a car travels 150 kilometers in 3.2 hours. Its average speed for the trip is","A car's speed would likely increase and decrease many times over a 3.2 hour trip. Its speed at a specific instant in time, however, is its instantaneous speed . A car's speedometer describes its instantaneous speed."],"figures":[{"sourceId":"fs-id1167066034560","filename":"CNX_HSPhysics_02_02_diagram.jpg","relativePath":"media/CNX_HSPhysics_02_02_diagram.jpg","alt":"A drawing is shown of a house on the left and a store on the right. The distance between the two is labeled three kilometers. A double-arrow vector between the house and the store is labeled with the equation change in d total equals zero."}],"tables":[]},{"uid":"hsphys.ch02.sec02.sub02","title":"Velocity","summaryVi":"Vận tốc (Velocity) là đại lượng VECTƠ bằng Độ dịch chuyển chia Thời gian (v = Δd / Δt). Vì mang dấu + hoặc − nên vận tốc cho biết cả độ nhanh chậm lẫn chiều chuyển động.","paragraphs":["The vector version of speed is velocity. Velocity describes the speed and direction of an object. As with speed, it is useful to describe either the average velocity over a time period or the velocity at a specific moment. Average velocity is displacement divided by the time over which the displacement occurs.","Velocity, like speed, has SI units of meters per second (m/s), but because it is a vector, you must also include a direction. Furthermore, the variable v for velocity is bold because it is a vector, which is in contrast to the variable v for speed which is italicized because it is a scalar quantity.","Suppose a passenger moved toward the back of a plane with an average velocity of –4 m/s. We cannot tell from the average velocity whether the passenger stopped momentarily or backed up before he got to the back of the plane. To get more details, we must consider smaller segments of the trip over smaller time intervals such as those shown in Figure 2.2. If you consider infinitesimally small intervals, you can define instantaneous velocity , which is the velocity at a specific instant in time. Instantaneous velocity and average velocity are the same if the velocity is constant.","Earlier, you have read that distance traveled can be different than the magnitude of displacement. In the same way, speed can be different than the magnitude of velocity. For example, you drive to a store and return home in half an hour. If your car’s odometer shows the total distance traveled was 6 km, then your average speed was 12 km/h. Your average velocity, however, was zero because your displacement for the round trip is zero."],"figures":[{"sourceId":"fs-id1167065974649","filename":"CNX_HSPhysics_02_02_plane.jpg","relativePath":"media/CNX_HSPhysics_02_02_plane.jpg","alt":"A drawing of an airplane facing to the right is shown, and is set in quadrant one of a coordinate plane. The x-axis is labeled df and then do. The distance between df and do is labeled with a left-pointing vector, change in d total. Four other vectors are shown below the airplane. Vector change in d a points to the left and is short. Vector change in d b points to the left and is also short. Vector change in d c points to the right and is short. Vector change in d d points to the left and is longer."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch02.sec02.ex01","number":"2.2.1","title":"Calculating Average Speed","problem":"A marble rolls 5.2 m in 1.8 s. What was the marble's average speed?","problemImages":[],"strategy":"We know the distance the marble travels, 5.2 m, and the time interval, 1.8 s. We can use these values in the average speed equation.","solution":"\\({v}_{\\text{avg}} = \\frac{\\text{distance}}{\\text{time}} = \\frac{5.2\\,\\text{m}}{1.8\\,\\text{s}} = 2.9\\,\\text{m/s}\\)","solutionImages":[],"solutionTables":[],"discussion":"Average speed is a scalar, so we do not include direction in the answer. We can check the reasonableness of the answer by estimating: 5 meters divided by 2 seconds is 2.5 m/s. Since 2.5 m/s is close to 2.9 m/s, the answer is reasonable. This is about the speed of a brisk walk, so it also makes sense."},{"uid":"hsphys.ch02.sec02.ex02","number":"2.2.2","title":"Calculating Average Velocity","problem":"A student has a displacement of 304 m north in 180 s. What was the student's average velocity?","problemImages":[],"strategy":"We know that the displacement is 304 m north and the time is 180 s. We can use the formula for average velocity to solve the problem.","solution":"\\({\\mathbf{v}}_{\\text{avg}} = \\frac{\\Delta \\mathbf{d}}{\\Delta t} = \\frac{304\\,\\text{m}}{180\\,\\text{s}} = 1.7\\,\\text{m/s north}\\)","solutionImages":[],"solutionTables":[],"discussion":"Since average velocity is a vector quantity, you must include direction as well as magnitude in the answer. Notice, however, that the direction can be omitted until the end to avoid cluttering the problem. Pay attention to the significant figures in the problem. The distance 304 m has three significant figures, but the time interval 180 s has only two, so the quotient should have only two significant figures.\nNote the way scalars and vectors are represented. In this book d represents distance and displacement. Similarly, v represents speed, and v represents velocity. A variable that is not bold indicates a scalar quantity, and a bold variable indicates a vector quantity. Vectors are sometimes represented by small arrows above the variable."},{"uid":"hsphys.ch02.sec02.ex03","number":"2.2.3","title":"Solving for Displacement when Average Velocity and Time are Known","problem":"Layla jogs with an average velocity of 2.4 m/s east. What is her displacement after 46 seconds?","problemImages":[],"strategy":"We know that Layla's average velocity is 2.4 m/s east, and the time interval is 46 seconds. We can rearrange the average velocity formula to solve for the displacement.","solution":"\\(\\begin{aligned} {\\mathbf{v}}_{\\text{avg}} = \\frac{\\Delta \\mathbf{d}}{\\Delta t} \\\\ \\Delta \\mathbf{d} = {\\mathbf{v}}_{avg}\\Delta t \\\\ = (2.4\\,\\text{m/s)(46 s)} \\\\ = 1.1 \\times {10}^{2}\\text{m east} \\end{aligned}\\)","solutionImages":[],"solutionTables":[],"discussion":"The answer is about 110 m east, which is a reasonable displacement for slightly less than a minute of jogging. A calculator shows the answer as 110.4 m. We chose to write the answer using scientific notation because we wanted to make it clear that we only used two significant figures.\nDimensional analysis is a good way to determine whether you solved a problem correctly. Write the calculation using only units to be sure they match on opposite sides of the equal mark. In the worked example, you have\nm = (m/s)(s). Since seconds is in the denominator for the average velocity and in the numerator for the time, the unit cancels out leaving only m and, of course, m = m."},{"uid":"hsphys.ch02.sec02.ex04","number":"2.2.4","title":"Solving for Time when Displacement and Average Velocity are Known","problem":"Phillip walks along a straight path from his house to his school. How long will it take him to get to school if he walks 428 m west with an average velocity of 1.7 m/s west?","problemImages":[],"strategy":"We know that Phillip's displacement is 428 m west, and his average velocity is 1.7 m/s west. We can calculate the time required for the trip by rearranging the average velocity equation.","solution":"\\(\\begin{aligned} {\\mathbf{v}}_{\\text{avg}} = \\frac{\\Delta \\mathbf{d}}{\\Delta t} \\\\ \\Delta t = \\frac{\\Delta \\mathbf{d}}{{\\mathbf{v}}_{\\text{avg}}} \\\\ = \\frac{428\\,\\text{m}}{1.7\\,\\text{m/s}} \\\\ = 2.5 \\times {10}^{2}\\text{s} \\end{aligned}\\)","solutionImages":[],"solutionTables":[],"discussion":"Here again we had to use scientific notation because the answer could only have two significant figures. Since time is a scalar, the answer includes only a magnitude and not a direction."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch02.sec02.feat01","type":"tip","title":"Tips for Success","text":"It is important to keep in mind that the average speed is not the same thing as the average velocity without its direction. Like we saw with displacement and distance in the last section, changes in direction over a time interval have a bigger effect on speed and velocity.","images":[]},{"uid":"hsphys.ch02.sec02.feat02","type":"tip","title":"Tips for Success","text":"Note the way scalars and vectors are represented. In this book d represents distance and displacement. Similarly, v represents speed, and v represents velocity. A variable that is not bold indicates a scalar quantity, and a bold variable indicates a vector quantity. Vectors are sometimes represented by small arrows above the variable.","images":[]},{"uid":"hsphys.ch02.sec02.feat03","type":"tip","title":"Tips for Success","text":"Dimensional analysis is a good way to determine whether you solved a problem correctly. Write the calculation using only units to be sure they match on opposite sides of the equal mark. In the worked example, you have\nm = (m/s)(s). Since seconds is in the denominator for the average velocity and in the numerator for the time, the unit cancels out leaving only m and, of course, m = m.","images":[]}],"summaryPoints":["Average speed is a scalar quantity that describes distance traveled divided by the time during which the motion occurs.","Velocity is a vector quantity that describes the speed and direction of an object.","Average velocity is displacement over the time period during which the displacement occurs. If the velocity is constant, then average velocity and instantaneous velocity are the same."],"glossary":[{"term":"average speed","termVi":"Tốc độ trung bình","ipa":"/ˈæv.ər.ɪdʒ spiːd/","definition":"distance traveled divided by time during which motion occurs","definitionVi":"Tổng quãng đường đi được chia cho tổng thời gian di chuyển (vô hướng, luôn ≥ 0).","memoryTipVi":"v_tb = Tổng quãng đường / Tổng thời gian."},{"term":"average velocity","termVi":"Vận tốc trung bình","ipa":"/ˈæv.ər.ɪdʒ vəˈlɒs.ə.ti/","definition":"displacement divided by time over which displacement occurs","definitionVi":"Độ dịch chuyển tổng cộng chia cho khoảng thời gian thực hiện: v_avg = Δd / Δt (đại lượng vectơ).","memoryTipVi":"Có thể dương, âm hoặc bằng 0!"},{"term":"instantaneous speed","termVi":"Tốc độ tức thời","ipa":"/ˌɪn.stənˈteɪ.ni.əs spiːd/","definition":"speed at a specific instant in time","definitionVi":"Độ lớn của vận tốc tức thời tại một thời điểm xác định (số chỉ trên đồng hồ tốc độ xe máy/ô tô).","memoryTipVi":"Tốc độ tức thời luôn bằng độ lớn của vận tốc tức thời."},{"term":"instantaneous velocity","termVi":"Vận tốc tức thời","ipa":"/ˌɪn.stənˈteɪ.ni.əs vəˈlɒs.ə.ti/","definition":"velocity at a specific instant in time","definitionVi":"Vận tốc của vật tại một thời điểm cụ thể (bằng độ dốc tiếp tuyến đồ thị d–t tại thời điểm đó).","memoryTipVi":"Gồm cả độ lớn tốc độ và hướng chuyển động ngay tại khoảnh khắc đó."},{"term":"speed","termVi":"Tốc độ","ipa":"/spiːd/","definition":"rate at which an object changes its location","definitionVi":"Đại lượng vô hướng cho biết vật chuyển động nhanh hay chậm (quãng đường / thời gian).","memoryTipVi":"⚠️ False Friend: Speed = Tốc độ (vô hướng), KHÔNG phải Vận tốc (Velocity)!"},{"term":"velocity","termVi":"Vận tốc (v)","ipa":"/vəˈlɒs.ə.ti/","definition":"the speed and direction of an object","definitionVi":"Đại lượng vectơ cho biết cả mức độ nhanh chậm lẫn hướng chuyển động của vật (độ dịch chuyển / thời gian).","memoryTipVi":"v < 0 nghĩa là vật đang đi ngược chiều dương quy ước."}],"assessments":[{"uid":"hsphys.ch02.sec02.q002","sourceId":"fs-id1167065951373","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"If you divide the total distance traveled on a car trip (as determined by the odometer) by the time for the trip, are you calculating the average speed or the magnitude of the average velocity, and under what circumstances are these two quantities the same?","images":[],"choices":[{"label":"a","text":"Average speed. Both are the same when the car is traveling at a constant speed and changing direction."},{"label":"b","text":"Average speed. Both are the same when the speed is constant and the car does not change its direction."},{"label":"c","text":"Magnitude of average velocity. Both are same when the car is traveling at a constant speed."},{"label":"d","text":"Magnitude of average velocity. Both are same when the car does not change its direction."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q004","sourceId":"fs-id1167065690097","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A pitcher throws a baseball from the pitchers mound to home plate in 0.46 s. The distance is 18.4 m. What was the average speed of the baseball?","images":[],"choices":[{"label":"a","text":"40 m/s"},{"label":"b","text":"- 40 m/s"},{"label":"c","text":"0.03 m/s"},{"label":"d","text":"8.5 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q007","sourceId":"fs-id1167065764598","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A bird flies with an average velocity of 7.5 m/s east from one branch to another in 2.4 s. It then pauses before flying with an average velocity of 6.8 m/s east for 3.5 s to another branch. What is the birds total displacement from its starting point?","images":[],"choices":[{"label":"a","text":"42 m west"},{"label":"b","text":"6 m west"},{"label":"c","text":"6 m east"},{"label":"d","text":"42 m east"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q008","sourceId":"eip-id1167066046311","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Which situation correctly describes when the moving mans position was negative but his velocity was positive?","images":[],"choices":[{"label":"a","text":"Man moving toward 0 from left of 0"},{"label":"b","text":"Man moving toward 0 from right of 0"},{"label":"c","text":"Man moving away from 0 from left of 0"},{"label":"d","text":"Man moving away from 0 from right of 0"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q012","sourceId":"fs-id1167065999793","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Terri, Aaron, and Jamal all walked along straight paths. Terri walked 3.95 km north in 48 min. Aaron walked 2.65 km west in 31 min. Jamal walked 6.50 km south in 81 min. Which of the following correctly ranks the three boys in order from lowest to highest average speed?","images":[],"choices":[{"label":"a","text":"Jamal, Terri, Aaron"},{"label":"b","text":"Jamal, Aaron, Terri"},{"label":"c","text":"Terri, Jamal, Aaron"},{"label":"d","text":"Aaron, Terri, Jamal"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q014","sourceId":"fs-id1167065690097","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A pitcher throws a baseball from the pitchers mound to home plate in 0.46 s. The distance is 18.4 m. What was the average speed of the baseball?","images":[],"choices":[{"label":"a","text":"40 m/s"},{"label":"b","text":"- 40 m/s"},{"label":"c","text":"0.03 m/s"},{"label":"d","text":"8.5 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q017","sourceId":"fs-id1167065764598","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A bird flies with an average velocity of 7.5 m/s east from one branch to another in 2.4 s. It then pauses before flying with an average velocity of 6.8 m/s east for 3.5 s to another branch. What is the birds total displacement from its starting point?","images":[],"choices":[{"label":"a","text":"42 m west"},{"label":"b","text":"6 m west"},{"label":"c","text":"6 m east"},{"label":"d","text":"42 m east"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q018","sourceId":"eip-id1167066046311","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Which situation correctly describes when the moving mans position was negative but his velocity was positive?","images":[],"choices":[{"label":"a","text":"Man moving toward 0 from left of 0"},{"label":"b","text":"Man moving toward 0 from right of 0"},{"label":"c","text":"Man moving away from 0 from left of 0"},{"label":"d","text":"Man moving away from 0 from right of 0"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q021","sourceId":"fs-id1167066137732","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A car travels with an average speed of 23 m/s for 82 s. Which of the following could NOT have been the car's displacement?","images":[],"choices":[{"label":"a","text":"1,700 m east"},{"label":"b","text":"2,000 m west"},{"label":"c","text":"1,600 m north"},{"label":"d","text":"1,500 m south"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q025","sourceId":"fs-id1167065974908","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What can you infer from the statement, Velocity of an object is zero ?","images":[],"choices":[{"label":"a","text":"Object is in linear motion with constant velocity."},{"label":"b","text":"Object is moving at a constant speed."},{"label":"c","text":"Object is either at rest or it returns to the initial point."},{"label":"d","text":"Object is moving in a straight line without changing its direction."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec02.q029","sourceId":"fs-id1167066046195","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A father and his daughter go to the bus stop that is located 75 m from their front door. The father walks in a straight line while his daughter runs along a varied path. Despite the different paths, they both end up at the bus stop at the same time. The fathers average speed is 2.2 m/s, and his daughters average speed is 3.5 m/s. (a) How long does it take the father and daughter to reach the bus stop? (b) What was the daughters total distance traveled? (c) If the daughter maintained her same average speed and traveled in a straight line like her father, how far beyond the bus stop would she have traveled?","images":[],"choices":[{"label":"a","text":"(a) 21.43 s (b) 75 m (c) 0 m"},{"label":"b","text":"(a) 21.43 s (b) 119 m (c) 44 m"},{"label":"c","text":"(a) 34 s (b) 75 m (c) 0 m"},{"label":"d","text":"(a) 34 s (b) 119 m (c) 44 m"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":2,"subsectionCount":2,"workedExampleCount":4,"snapLabCount":0,"glossaryCount":6,"assessmentCount":11}},{"uid":"hsphys.ch02.sec03","moduleId":"m54110","number":"2.3","slug":"position-vs-time-graphs","title":"Position vs. Time Graphs","isIntroduction":false,"learningObjectives":["Explain the meaning of slope in position vs. time graphs","Solve problems using position vs. time graphs"],"bilingualGuide":{"notebookSummaryVi":"Đồ thị Vị trí – Thời gian (d–t): Độ dốc (Slope) của đồ thị d–t chính là VẬN TỐC (Velocity) của vật!","wordProblemCues":[{"phraseEn":"slope of position-time graph","meaningVi":"Độ dốc đồ thị d–t = Vận tốc v","mathNotation":"Slope = Δd/Δt = v"}],"commonTrapsVi":["Đường đi xuống trên đồ thị d–t (độ dốc âm) KHÔNG có nghĩa là vật 'xuống dốc', mà là vật đi theo chiều âm (ngược chiều dương quy ước)!"]},"keyEquations":[{"name":"Displacement","formula":"\\(\\mathbf{d} = {\\mathbf{d}}_{0} + \\mathbf{v}t\\) ."}],"subsections":[{"uid":"hsphys.ch02.sec03.sub01","title":"Graphing Position as a Function of Time","summaryVi":"Cách vẽ và đọc đồ thị Vị trí – Thời gian (d–t): Độ dốc (Slope = Δd / Δt) chính là Vận tốc! Đường thẳng xiên lên là đi theo chiều dương, xiên xuống là đi theo chiều âm, nằm ngang là đứng yên.","paragraphs":["A graph , like a picture, is worth a thousand words. Graphs not only contain numerical information, they also reveal relationships between physical quantities. In this section, we will investigate kinematics by analyzing graphs of position over time .","Graphs in this text have perpendicular axes, one horizontal and the other vertical. When two physical quantities are plotted against each other, the horizontal axis is usually considered the independent variable , and the vertical axis is the dependent variable . In algebra, you would have referred to the horizontal axis as the x -axis and the vertical axis as the y -axis. As in Figure 2.3, a straight-line graph has the general form \\(y = mx + b\\) .","Here m is the slope, defined as the rise divided by the run (as seen in the figure) of the straight line. The letter b is the y -intercept which is the point at which the line crosses the vertical, y -axis. In terms of a physical situation in the real world, these quantities will take on a specific significance, as we will see below. (Figure 2.3.)","In physics, time is usually the independent variable. Other quantities, such as displacement, are said to depend upon it. A graph of position versus time, therefore, would have position on the vertical axis (dependent variable) and time on the horizontal axis (independent variable). In this case, to what would the slope and y -intercept refer? Let’s look back at our original example when studying distance and displacement.","The drive to school was 5 km from home. Let’s assume it took 10 minutes to make the drive and that your parent was driving at a constant velocity the whole time. The position versus time graph for this section of the trip would look like that shown in Figure 2.3.","As we said before, d 0 = 0 because we call home our O and start calculating from there. In Figure 2.3, the line starts at d = 0, as well. This is the b in our equation for a straight line. Our initial position in a position versus time graph is always the place where the graph crosses the x -axis at t = 0. What is the slope? The rise is the change in position, (i.e., displacement) and the run is the change in time. This relationship can also be written","This relationship was how we defined average velocity. Therefore, the slope in a d versus t graph, is the average velocity.","Let’s look at another example. Figure 2.3 shows a graph of position versus time for a jet-powered car on a very flat dry lake bed in Nevada.","Using the relationship between dependent and independent variables, we see that the slope in the graph in Figure 2.3 is average velocity, v avg and the intercept is displacement at time zero—that is, d 0 . Substituting these symbols into y = mx + b gives","or","Thus a graph of position versus time gives a general relationship among displacement, velocity, and time, as well as giving detailed numerical information about a specific situation. From the figure we can see that the car has a position of 400 m at t = 0 s, 650 m at t = 1.0 s, and so on. And we can learn about the object’s velocity, as well.","So how do we use graphs to solve for things we want to know like velocity?","But what if the graph of the position is more complicated than a straight line? What if the object speeds up or turns around and goes backward? Can we figure out anything about its velocity from a graph of that kind of motion? Let’s take another look at the jet-powered car. The graph in Figure 2.3 shows its motion as it is getting up to speed after starting at rest. Time starts at zero for this motion (as if measured with a stopwatch), and the displacement and velocity are initially 200 m and 15 m/s, respectively.","The graph of position versus time in Figure 2.3 is a curve rather than a straight line. The slope of the curve becomes steeper as time progresses, showing that the velocity is increasing over time. The slope at any point on a position-versus-time graph is the instantaneous velocity at that point. It is found by drawing a straight line tangent to the curve at the point of interest and taking the slope of this straight line. Tangent lines are shown for two points in Figure 2.3. The average velocity is the net displacement divided by the time traveled."],"figures":[{"sourceId":"fs-id1167066871009","filename":"CNX_HSPhysics_02_03_graph.jpg","relativePath":"media/CNX_HSPhysics_02_03_graph.jpg","alt":"A line graph is shown. The plotted line has a positive slope. The point of intersection with the y-axis is labeled intercept, b. The distance between the graphed line and the x-axis at the intercept is also labeled b. The line is labeled with the equation y equals m x plus b. The equation slope equals rise over run equals change in x over change in y equals m is also shown."},{"sourceId":"fs-id1167067104108","filename":"CNX_HSPhysics_02_03_position.jpg","relativePath":"media/CNX_HSPhysics_02_03_position.jpg","alt":"A line graph of position versus time is shown. The scale on the x-axis is from zero to twelve in increments of one, and is labeled time in minutes. The scale on the y-axis is from zero to twelve in increments of one and is labeled position in kilometers. A line of the equation y equals point five x is graphed and ends at ten minutes."},{"sourceId":"fs-id1167066828835","filename":"CNX_HSPhysics_02_03_time.jpg","relativePath":"media/CNX_HSPhysics_02_03_time.jpg","alt":"A line graph is shown. The x-axis is labeled time in seconds and has a scale from zero to eight in increments of one. The y-axis is labeled position, d, in meters and has a scale from zero to two thousand four hundred in increments of four hundred. A line is plotted that intersects the following data points: zero, four hundred (labeled d 0 equals four hundred), point five, five hundred twenty-five; and six point four, two thousand (labeled y equals d o plus bar over v times t). The line is labeled Slope equals bar over v equals change in d over change in t. The distance between points point five, five hundred twenty-five and six point four, two thousand is labeled change in t. The distance between points six point four, five hundred twenty-five and six point four, two thousand is labeled change in d."},{"sourceId":"fs-id1167063917611","filename":"CNX_HSPhysics_02_03_jet.jpg","relativePath":"media/CNX_HSPhysics_02_03_jet.jpg","alt":"A line graph titled Jet Car Displacement is shown. The x-axis is labeled time, t, in seconds and has a scale from zero to forty on increments of ten. The y-axis is labeled displacement, x, in meters and has a scale from zero to three thousand five hundred in increments of five hundred. The following approximate data points are plotted, resulting in a line that curves upward: eight, two hundred fifty; ten, five hundred; fifteen, one thousand; twenty, one thousand five hundred; twenty-five, two thousand; thirty, three thousand. A right triangle is drawn at points eight, two hundred fifty; twelve, two hundred fifty, and twelve seven hundred fifty. The legs are labeled change in tp and change in dp. Point ten, five hundred is labeled P. Another right triangle is drawn at points twenty, one thousand five hundred; thirty, one thousand five hundred, and thirty, three thousand. The legs are labeled change in tq and change in dq. Point twenty-five, two thousand is labeled Q."},{"sourceId":"fs-id1167066948168","filename":"CNX_HSPhysics_02_03_airforce.jpg","relativePath":"media/CNX_HSPhysics_02_03_airforce.jpg","alt":"A photograph of a United States Air Force jet car is shown speeding down a track. Smoke is billowing from the back end."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch02.sec03.ex01","number":"2.3.1","title":"Using Position–Time Graph to Calculate Average Velocity: Jet Car","problem":"Find the average velocity of the car whose position is graphed in Figure 1.13 .","problemImages":[],"strategy":"The slope of a graph of d vs. t is average velocity, since slope equals rise over run.\n\\(\\text{slope =}\\frac{\\Delta \\mathbf{d}}{\\Delta t} = \\mathbf{v}\\)\nSince the slope is constant here, any two points on the graph can be used to find the slope.","solution":"Choose two points on the line. In this case, we choose the points labeled on the graph: (6.4 s, 2000 m) and (0.50 s, 525 m). (Note, however, that you could choose any two points.)\nSubstitute the d and t values of the chosen points into the equation. Remember in calculating change (Δ) we always use final value minus initial value.\n\\(\\begin{aligned} \\mathbf{v} = \\frac{\\Delta \\mathbf{d}}{\\Delta t} \\\\ = \\frac{2000\\,\\text{m} - 525\\,\\text{m}}{6.4\\,\\text{s} - 0.50\\,\\text{s}} \\\\ = 250\\,\\text{m/s} \\end{aligned},\\)","solutionImages":[],"solutionTables":[],"discussion":"This is an impressively high land speed (900 km/h, or about 560 mi/h): much greater than the typical highway speed limit of 27 m/s or 96 km/h, but considerably shy of the record of 343 m/s or 1,234 km/h, set in 1997."},{"uid":"hsphys.ch02.sec03.ex02","number":"2.3.2","title":"Using Position–Time Graph to Calculate Average Velocity: Jet Car, Take Two","problem":"Calculate the instantaneous velocity of the jet car at a time of 25 s by finding the slope of the tangent line at point Q in Figure 2.3.","problemImages":[],"strategy":"The slope of a curve at a point is equal to the slope of a straight line tangent to the curve at that point.","solution":"Find the tangent line to the curve at \\(t = 25\\,\\text{s}\\) .\nDetermine the endpoints of the tangent. These correspond to a position of 1,300 m at time 19 s and a position of 3120 m at time 32 s.\nPlug these endpoints into the equation to solve for the slope, v .\n\\(\\begin{aligned} \\text{slope} \\text{=} {v}_{Q} = \\frac{\\Delta {d}_{Q}}{\\Delta {t}_{Q}} \\\\ \\text{=} \\frac{(3120 - 1300)\\text{m}}{(32 - 19)\\text{s}} \\\\ \\text{=} \\frac{1820\\,\\text{m}}{13\\,\\text{s}} \\\\ \\text{=} 140\\,\\text{m/s} \\end{aligned}\\)","solutionImages":[],"solutionTables":[],"discussion":"The entire graph of v versus t can be obtained in this fashion."}],"snapLabs":[{"uid":"hsphys.ch02.sec03.lab01","title":"Graphing Motion","text":"In this activity, you will release a ball down a ramp and graph the ball’s displacement vs. time.\nChoose an open location with lots of space to spread out so there is less chance for tripping or falling due to rolling balls.\n1 ball\n1 board\n2 or 3 books\n1 stopwatch\n1 tape measure\n6 pieces of masking tape\n1 piece of graph paper\n1 pencil\nProcedure\nBuild a ramp by placing one end of the board on top of the stack of books. Adjust location, as necessary, until there is no obstacle along the straight line path from the bottom of the ramp until at least the next 3 m.\nMark distances of 0.5 m, 1.0 m, 1.5 m, 2.0 m, 2.5 m, and 3.0 m from the bottom of the ramp. Write the distances on the tape.\nHave one person take the role of the experimenter. This person will release the ball from the top of the ramp. If the ball does not reach the 3.0 m mark, then increase the incline of the ramp by adding another book. Repeat this Step as necessary.\nHave the experimenter release the ball. Have a second person, the timer, begin timing the trial once the ball reaches the bottom of the ramp and stop the timing once the ball reaches 0.5 m. Have a third person, the recorder, record the time in a data table.\nRepeat Step 4, stopping the times at the distances of 1.0 m, 1.5 m, 2.0 m, 2.5 m, and 3.0 m from the bottom of the ramp.\nUse your measurements of time and the displacement to make a position vs. time graph of the ball’s motion.\nRepeat Steps 4 through 6, with different people taking on the roles of experimenter, timer, and recorder. Do you get the same measurement values regardless of who releases the ball, measures the time, or records the result? Discuss possible causes of discrepancies, if any.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch02.sec03.feat01","type":"tip","title":"Tips for Success","text":"Sometimes, as is the case where we graph both the trip to school and the return trip, the behavior of the graph looks different during different time intervals. If the graph looks like a series of straight lines, then you can calculate the average velocity for each time interval by looking at the slope. If you then want to calculate the average velocity for the entire trip, you can do a weighted average.","images":[]}],"summaryPoints":["Graphs can be used to analyze motion.","The slope of a position vs. time graph is the velocity.","For a straight line graph of position, the slope is the average velocity.","To obtain the instantaneous velocity at a given moment for a curved graph, find the tangent line at that point and take its slope."],"glossary":[{"term":"dependent variable","termVi":"Biến phụ thuộc","ipa":"/dɪˈpen.dənt ˈveə.ri.ə.bəl/","definition":"the variable that changes as the independent variable changes","definitionVi":"Đại lượng thay đổi phụ thuộc vào biến khác (vẽ trên trục đứng y).","memoryTipVi":"Trên đồ thị d–t, vị trí d phụ thuộc vào thời gian t."},{"term":"independent variable","termVi":"Biến độc lập","ipa":"/ˌɪn.dɪˈpen.dənt ˈveə.ri.ə.bəl/","definition":"the variable, usually along the horizontal axis of a graph, that does not change based on human or experimental action; in physics this is usually time","definitionVi":"Đại lượng thay đổi độc lập (thời gian t, luôn vẽ trên trục ngang x).","memoryTipVi":"Thời gian luôn nằm ở trục hoành."},{"term":"tangent","termVi":"Đường tiếp tuyến","ipa":"/ˈtæn.dʒənt/","definition":"a line that touches another at exactly one point","definitionVi":"Đường thẳng chỉ chạm vào đường cong đồ thị tại đúng một điểm; độ dốc tiếp tuyến đồ thị d–t chính là vận tốc tức thời.","memoryTipVi":"Khái niệm cầu nối trực tiếp sang Đạo hàm trong Giải tích!"}],"assessments":[{"uid":"hsphys.ch02.sec03.q001","sourceId":"fs-id1167066808934","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which of the following information about motion can be determined by looking at a position vs. time graph that is a straight line?","images":[],"choices":[{"label":"a","text":"frame of reference"},{"label":"b","text":"average acceleration"},{"label":"c","text":"velocity"},{"label":"d","text":"direction of force applied"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q003","sourceId":"fs-id1167063726038","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Calculate the average velocity of the object shown in the graph below over the whole time interval.","images":[{"sourceId":"fs-id1169832876228","filename":"CNX_HSPhysics_02_03_line_img.jpg","relativePath":"media/CNX_HSPhysics_02_03_line_img.jpg","alt":"The image depicts a graph titled 'position vs time' with position (m) on the y-axis and time (s) on the x-axis. The data points graphed trend upward in an evenly distributed straight line from left to right."}],"choices":[{"label":"a","text":"0.25 m/s"},{"label":"b","text":"0.31 m/s"},{"label":"c","text":"3.2 m/s"},{"label":"d","text":"4.00 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q005","sourceId":"fs-id1167063693172","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Use the graph to describe what the runner’s motion looks like.\nHow are average velocity for only the first four seconds and instantaneous velocity related? What is the runner's net displacement over the time shown?","images":[{"sourceId":"fs-id1164567559201","filename":"CNX_HSPhysics_02_03_runner_img.jpg","relativePath":"media/CNX_HSPhysics_02_03_runner_img.jpg","alt":"A graph titled Runner Position plots time (s) on the x axis, and position (m) on the y axis. A line extends from the origin with a slope of 3. At point (12, 4), it extends without a slope and points (12, 6), (12, 8), and (12, 10) are marked."}],"choices":[{"label":"a","text":"The net displacement is 12 m and the average velocity is equal to the instantaneous velocity."},{"label":"b","text":"The net displacement is 12 m and the average velocity is two times the instantaneous velocity."},{"label":"c","text":"The net displacement is 10 + 12 = 22 m and the average velocity is equal to the instantaneous velocity."},{"label":"d","text":"The net displacement is 10 + 12 = 22 m and the average velocity is two times the instantaneous velocity."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q007","sourceId":"fs-id1167067044146","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":false,"prompt":"Explain how you can use the graph of position vs. time to describe the change in velocity over time.\nIdentify the time ( t a , t b , t c , t d , or t e ) at which at which the instantaneous velocity is greatest, the time at which it is zero, and the time at which it is negative.","images":[{"sourceId":"veloc","filename":"Physics_02_03_veloc.jpg","relativePath":"media/Physics_02_03_veloc.jpg","alt":"A position-time graph (x vs. t) showing an object's motion with decreasing positive velocity from points a to c, reaching zero velocity at d, and remaining stationary at e."}],"choices":[],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q008","sourceId":"fs-id1167063726038","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Calculate the average velocity of the object shown in the graph below over the whole time interval.","images":[{"sourceId":"fs-id1169832876228","filename":"CNX_HSPhysics_02_03_line_img.jpg","relativePath":"media/CNX_HSPhysics_02_03_line_img.jpg","alt":"The image depicts a graph titled 'position vs time' with position (m) on the y-axis and time (s) on the x-axis. The data points graphed trend upward in an evenly distributed straight line from left to right."}],"choices":[{"label":"a","text":"0.25 m/s"},{"label":"b","text":"0.31 m/s"},{"label":"c","text":"3.2 m/s"},{"label":"d","text":"4.00 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q010","sourceId":"fs-id1167067216542","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Using the graph, what is the average velocity for the whole 10 seconds?","images":[{"sourceId":"fs-id1164565407354","filename":"CNX_HSPhysics_02_03_runner_img.jpg","relativePath":"media/CNX_HSPhysics_02_03_runner_img.jpg","alt":"A graph titled Runner Position plots time (s) on the x axis, and position (m) on the y axis. A line extends from the origin with a slope of 3. At point (12, 4), it extends without a slope and points (12, 6), (12, 8), and (12, 10) are marked."}],"choices":[{"label":"a","text":"The total average velocity is 0 m/s."},{"label":"b","text":"The total average velocity is 1.2 m/s."},{"label":"c","text":"The total average velocity is 1.5 m/s."},{"label":"d","text":"The total average velocity is 3.0 m/s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q012","sourceId":"fs-id1167063556429","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the slope of a straight line graph of position vs. time?","images":[],"choices":[{"label":"a","text":"Velocity"},{"label":"b","text":"Displacement"},{"label":"c","text":"Distance"},{"label":"d","text":"Acceleration"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q013","sourceId":"fs-id1167067193716","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Using the graph, what is the runner’s velocity from 4 to 10 s?","images":[{"sourceId":"testprep","filename":"CNX_HSPhysics_02_03_runner_img.jpg","relativePath":"media/CNX_HSPhysics_02_03_runner_img.jpg","alt":"A line graph titled 'Runner Position' shows a runner's position (m) over time (s). The runner moves from 0m to 12m in the first 4 seconds, then remains at 12m from 4 to 10 seconds."}],"choices":[{"label":"a","text":"–3 m/s"},{"label":"b","text":"0 m/s"},{"label":"c","text":"1.2 m/s"},{"label":"d","text":"3 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q014","sourceId":"fs-id1167066945162","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A hockey puck is shot down the arena in a straight line. Assume it does not slow until it is stopped by an opposing player who sends it back in the direction it came. The players are 20 m apart and it takes 1 s for the puck to go there and back. Which of the following describes the graph of the displacement over time? Consider the initial direction of the puck to be positive.","images":[],"choices":[{"label":"a","text":"The graph is an upward opening V."},{"label":"b","text":"The graph is a downward opening V."},{"label":"c","text":"The graph is an upward opening U."},{"label":"d","text":"The graph is downward opening U."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q015","sourceId":"fs-id1167066847657","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A defensive player kicks a soccer ball 20 m back to her own goalie. It stops just as it reaches her. She sends it back to the player. Without knowing the time it takes, draw a rough sketch of the displacement over time. Does this graph look similar to the graph of the hockey puck from the previous question?","images":[],"choices":[{"label":"a","text":"Yes, the graph is similar to the graph of the hockey puck."},{"label":"b","text":"No, the graph is not similar to the graph of the hockey puck."},{"label":"c","text":"The graphs cannot be compared without knowing the time the soccer ball was rolling."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q016","sourceId":"fs-id1167063915147","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What are the net displacement, total distance traveled, and total average velocity in the previous two problems?","images":[],"choices":[{"label":"a","text":"net displacement = 0 m, total distance = 20 m, total average velocity = 20 m/s"},{"label":"b","text":"net displacement = 0 m, total distance = 40 m, total average velocity = 20 m/s"},{"label":"c","text":"net displacement = 0 m, total distance = 20 m, total average velocity = 0 m/s"},{"label":"d","text":"net displacement = 0 m, total distance = 40 m, total average velocity = 0 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q018","sourceId":"fs-id1167063772262","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"What kind of motion would create a position graph like the one shown?","images":[{"sourceId":"fs-id1169830662478","filename":"CNX_HSPhysics_02_03_versus_img.jpg","relativePath":"media/CNX_HSPhysics_02_03_versus_img.jpg","alt":"A position versus time graph illustrates an object's increasing position over time, with the red line indicating an accelerating motion as the slope becomes steeper."}],"choices":[{"label":"a","text":"uniform motion"},{"label":"b","text":"any motion that accelerates"},{"label":"c","text":"motion that stops and then starts"},{"label":"d","text":"motion that has constant velocity"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec03.q019","sourceId":"fs-id1167066793176","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"What is the average velocity for the whole time period shown in the graph?","images":[{"sourceId":"fs-id1169832834650","filename":"CNX_HSPhysics_02_03_vs_img.jpg","relativePath":"media/CNX_HSPhysics_02_03_vs_img.jpg","alt":"A position-time graph showing an object's position in meters (y-axis) versus time in seconds (x-axis). The object moves from 0m to 2m, then to -3m, stays at -3m, and finally moves to -2m."}],"choices":[{"label":"a","text":"\\(–\\frac{1}{3}\\text{m/s}\\)"},{"label":"b","text":"\\(–\\frac{3}{4}\\text{m/s}\\)"},{"label":"c","text":"\\(\\frac{1}{3}\\text{m/s}\\)"},{"label":"d","text":"\\(\\frac{3}{4}\\text{m/s}\\)"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":1,"subsectionCount":1,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":3,"assessmentCount":13}},{"uid":"hsphys.ch02.sec04","moduleId":"m54094","number":"2.4","slug":"velocity-vs-time-graphs","title":"Velocity vs. Time Graphs","isIntroduction":false,"learningObjectives":["Explain the meaning of slope and area in velocity vs. time graphs","Solve problems using velocity vs. time graphs"],"bilingualGuide":{"notebookSummaryVi":"Đồ thị Vận tốc – Thời gian (v–t): Độ dốc là Gia tốc (a = Δv/Δt), còn Diện tích dưới đường biểu diễn là Độ dịch chuyển (Δd)!","wordProblemCues":[{"phraseEn":"area under velocity-time graph","meaningVi":"Diện tích dưới đồ thị v–t = Độ dịch chuyển Δd","mathNotation":"Area = Δd"},{"phraseEn":"slope of velocity-time graph","meaningVi":"Độ dốc đồ thị v–t = Gia tốc a","mathNotation":"Slope = Δv/Δt = a"}],"commonTrapsVi":["Đường nằm ngang trên đồ thị d–t là ĐỨNG YÊN (v = 0), nhưng đường nằm ngang trên đồ thị v–t là CHUYỂN ĐỘNG THẲNG ĐỀU (v = hằng số ≠ 0)!"]},"keyEquations":[{"name":"Velocity","formula":"\\(\\mathbf{v} = {\\mathbf{v}}_{0} + at\\)"},{"name":"Acceleration","formula":"\\(\\mathbf{a} = \\frac{\\Delta \\mathbf{v}}{\\Delta t}\\)"}],"subsections":[{"uid":"hsphys.ch02.sec04.sub01","title":"Graphing Velocity as a Function of Time","summaryVi":"Cách đọc đồ thị Vận tốc – Thời gian (v–t): Độ dốc của đồ thị v–t chính là Gia tốc (a = Δv / Δt), còn Diện tích hình phẳng nằm giữa đường biểu diễn và trục thời gian chính là Độ dịch chuyển Δd!","paragraphs":["Earlier, we examined graph s of position versus time . Now, we are going to build on that information as we look at graphs of velocity vs. time. Velocity is the rate of change of displacement . Acceleration is the rate of change of velocity; we will discuss acceleration more in another chapter. These concepts are all very interrelated.","In this simulation you will use a vector diagram to manipulate a ball into a certain location without hitting a wall. You can manipulate the ball directly with position or by changing its velocity. Explore how these factors change the motion. If you would like, you can put it on the a setting, as well. This is acceleration, which measures the rate of change of velocity. We will explore acceleration in more detail later, but it might be interesting to take a look at it here.","What can we learn about motion by looking at velocity vs. time graphs? Let’s return to our drive to school, and look at a graph of position versus time as shown in Figure 2.4.","We assumed for our original calculation that your parent drove with a constant velocity to and from school. We now know that the car could not have gone from rest to a constant velocity without speeding up. So the actual graph would be curved on either end, but let’s make the same approximation as we did then, anyway.","Looking at this graph, and given what we learned, we can see that there are two distinct periods to the car’s motion—the way to school and the way back. The average velocity for the drive to school is 0.5 km/minute. We can see that the average velocity for the drive back is –0.5 km/minute. If we plot the data showing velocity versus time, we get another graph (Figure 2.4):","We can learn a few things. First, we can derive a v versus t graph from a d versus t graph. Second, if we have a straight-line position–time graph that is positively or negatively sloped, it will yield a horizontal velocity graph. There are a few other interesting things to note. Just as we could use a position vs. time graph to determine velocity, we can use a velocity vs. time graph to determine position. We know that v = d / t . If we use a little algebra to re-arrange the equation, we see that d = v \\(\\times\\) t . In Figure 2.4, we have velocity on the y -axis and time along the x -axis. Let’s take just the first half of the motion. We get 0.5 km/minute \\(\\times\\) 10 minutes. The units for minutes cancel each other, and we get 5 km, which is the displacement for the trip to school. If we calculate the same for the return trip, we get –5 km. If we add them together, we see that the net displacement for the whole trip is 0 km, which it should be because we started and ended at the same place.","The area under a velocity curve represents the displacement. The velocity curve also tells us whether the car is speeding up. In our earlier example, we stated that the velocity was constant. So, the car is not speeding up. Graphically, you can see that the slope of these two lines is 0. This slope tells us that the car is not speeding up, or accelerating. We will do more with this information in a later chapter. For now, just remember that the area under the graph and the slope are the two important parts of the graph. Just like we could define a linear equation for the motion in a position vs. time graph, we can also define one for a velocity vs. time graph. As we said, the slope equals the acceleration, a . And in this graph, the y -intercept is v 0 . Thus, \\(\\mathbf{v} = {\\mathbf{v}}_{0} + \\mathbf{a}t\\) .","But what if the velocity is not constant? Let’s look back at our jet-car example. At the beginning of the motion, as the car is speeding up, we saw that its position is a curve, as shown in Figure 2.4.","You do not have to do this, but you could, theoretically, take the instantaneous velocity at each point on this graph. If you did, you would get Figure 2.4, which is just a straight line with a positive slope.","Again, if we take the slope of the velocity vs. time graph, we get the acceleration, the rate of change of the velocity. And, if we take the area under the slope, we get back to the displacement."],"figures":[{"sourceId":"fs-id1167066012169","filename":"CNX_HSPhysics_02_04_drive.jpg","relativePath":"media/CNX_HSPhysics_02_04_drive.jpg","alt":"A line graph titled Position versus Time is shown. The x-axis is labeled time in minutes and has a scale from zero to twenty in increments of one. The y-axis is labeled position, d, in kilometers and has a scale from zero to twelve in increments of one. The line intersects the following data points to form a line that slopes upward and then downward: zero, zero; two, one; four, two; ten, five; twelve, four; fourteen, three; twenty, zero."},{"sourceId":"fs-id1167065046778","filename":"CNX_HSPhysics_02_04_velocity.jpg","relativePath":"media/CNX_HSPhysics_02_04_velocity.jpg","alt":"A graph that shows time in minutes on the x-axis and velocity in kilometers per minute on the y axis. A horizontal line is show at a velocity of 0.5 that runs from 0 to 10 minutes. Another horizontal line is shown at a velocity of –0.5 that runs from 10 to 20 minutes."},{"sourceId":"fs-id1167064948425","filename":"CNX_HSPhysics_02_04_car.jpg","relativePath":"media/CNX_HSPhysics_02_04_car.jpg","alt":"A line graph titled Jet Car Displacement is shown. The x-axis is labeled time, t, in seconds and has a scale from zero to forty on increments of ten. The y-axis is labeled displacement, x, in meters and has a scale from zero to three thousand five hundred in increments of five hundred. The following approximate data points are plotted, resulting in a line that curves upward: eight, two hundred fifty; ten, five hundred; fifteen, one thousand; twenty, one thousand five hundred; twenty-five, two thousand; thirty, three thousand. A right triangle is drawn at points eight, two hundred fifty; twelve, two hundred fifty, and twelve seven hundred fifty. The legs are labeled change in tp and change in dp. Point ten, five hundred is labeled P. Another right triangle is drawn at points twenty, one thousand five hundred; thirty, one thousand five hundred, and thirty, three thousand. The legs are labeled change in tq and change in dq. Point twenty-five, two thousand is labeled Q."},{"sourceId":"fs-id1167065864880","filename":"CNX_HSPhysics_02_04_power.jpg","relativePath":"media/CNX_HSPhysics_02_04_power.jpg","alt":"A line graph titled Jet Car Velocity is shown. The x-axis is labeled time, t, in seconds and has a scale from zero to forty on increments of ten. The y-axis is labeled velocity, v, in meters per second and has a scale from zero to one hundred eighty in increments of twenty. A straight line with a positive slope is plotted that intersects the following approximate points: zero, eighteen; ten, sixty (labeled P); fifteen, ninety; twenty, one hundred twenty; twenty five, one hundred fifty (labeled Q); thirty, one hundred sixty. Slope equals a is shown above the graphed lined."}],"tables":[]},{"uid":"hsphys.ch02.sec04.sub02","title":"Solving Problems using Velocity–Time Graphs","summaryVi":"Thực hành tính Độ dịch chuyển bằng cách chia phần diện tích dưới đồ thị v–t thành các hình chữ nhật và hình tam giác rồi cộng lại.","paragraphs":["Most velocity vs. time graphs will be straight lines. When this is the case, our calculations are fairly simple.","Most of the velocity vs. time graphs we will look at will be simple to interpret. Occasionally, we will look at curved graphs of velocity vs. time. More often, these curved graphs occur when something is speeding up, often from rest. Let’s look back at a more realistic velocity vs. time graph of the jet car’s motion that takes this speeding up stage into account."],"figures":[{"sourceId":"fs-id1167065733764","filename":"CNX_HSPhysics_02_04_accurate.jpg","relativePath":"media/CNX_HSPhysics_02_04_accurate.jpg","alt":"A line graph titled Jet Car Velocity is shown. The x-axis is labeled time, t, in seconds and has a scale from zero to eighty on increments of ten. The y-axis is labeled velocity, v, in meters per second and has a scale from one hundred sixty to two hundred sixty in increments of ten. The following approximate data points are plotted and connected to form a line that curves upward, and then becomes flat: zero, one hundred sixty five; ten, two hundred ten; twenty, two hundred thirty; thirty, two hundred forty; forty, two hundred forty-five; fifty, two hundred forty-five; sixty, two hundred forty-five; seventy, two hundred forty-five. A right triangle is drawn, with a hypotenuse that intersects points twenty, two hundred thirty and thirty, two hundred forty. The bottom leg of the triangle has ends at points zero, two hundred ten and fifty, two hundred ten and is labeled change in t. The upright leg has ends at points fifty, two hundred ten and fifty, two hundred sixty and is labeled change in v."}],"tables":[]},{"uid":"hsphys.ch02.sec04.sub03","title":"Performance Task","summaryVi":"Dự án thực hành tổng hợp cuối chương về phân tích đồ thị chuyển động.","paragraphs":["The National Mall in Washington, DC, is a national park containing most of the highly treasured memorials and museums of the United States. However, the National Mall also hosts many events and concerts. The map below shows the area for a benefit concert during which the president will speak. The concert stage is near the Lincoln Memorial. The seats and standing room for the crowd will stretch from the stage east to near the Washington Monument, as shown on the map. You are planning the logistics for the concert. Use the map scale to measure any distances needed to make the calculations below.","The park has three new long-distance speakers. They would like to use these speakers to broadcast the concert audio to other parts of the National Mall. The speakers can project sound up to 0.35 miles away but they must be connected to one of the power supplies within the concert area. What is the minimum amount of wire needed for each speaker, in miles, in order to project the audio to the following areas? Assume that wire cannot be placed over buildings or any memorials.","Part A. The center of the Jefferson Memorial using power supply 1 (This will involve an elevated wire that can travel over water.)","Part B. The center of the Ellipse using power supply 3 (This wire cannot travel over water.)","Part C. The president’s motorcade will be traveling to the concert from the White House. To avoid concert traffic, the motorcade travels from the White House west down E Street and then turns south on 23rd Street to reach the Lincoln memorial. What minimum speed, in miles per hour to the nearest tenth, would the motorcade have to travel to make the trip in 5 minutes?","Part D. The president could also simply fly from the White House to the Lincoln Memorial using the presidential helicopter, Marine 1. How long would it take Marine 1, traveling slowly at 30 mph, to travel from directly above the White House landing zone (LZ) to directly above the Lincoln Memorial LZ? Disregard liftoff and landing times and report the travel time in minutes to the nearest minute."],"figures":[{"sourceId":"fs-id1167065865867","filename":"CNX_HSPhysics_02_04_map_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_map_img.jpg","alt":"A map drawing of the National Mall area of Washington, DC is shown. A red line is drawn on the map to show the presidential motorcade route from the White House at the top right of the map to a concert stage near the Lincoln Memorial at the bottom left of the map.  Three points, one, two, and three, are plotted in the center of the map. Points one and two are directly across from each other. Point three is in between and slightly above points one and two."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch02.sec04.ex01","number":"2.4.1","title":"Using Velocity Graph to Calculate Some Stuff: Jet Car","problem":"Use this figure to (a) find the displacement of the jet car over the time shown (b) calculate the rate of change (acceleration) of the velocity. (c) give the instantaneous velocity at 5 s, and (d) calculate the average velocity over the interval shown.","problemImages":[],"strategy":"The displacement is given by finding the area under the line in the velocity vs. time graph.\nThe acceleration is given by finding the slope of the velocity graph.\nThe instantaneous velocity can just be read off of the graph.\nTo find the average velocity, recall that \\({\\mathbf{v}}_{\\text{avg}} = \\frac{\\Delta \\mathbf{d}}{\\Delta t} = \\frac{{\\mathbf{d}}_{\\text{f}} - {\\mathbf{d}}_{0}}{{t}_{\\text{f}} - {t}_{0}}\\)","solution":"Analyze the shape of the area to be calculated. In this case, the area is made up of a rectangle between 0 and 20 m/s stretching to 30 s. The area of a rectangle is length \\(\\times\\) width. Therefore, the area of this piece is 600 m.\nAbove that is a triangle whose base is 30 s and height is 140 m/s. The area of a triangle is 0.5 \\(\\times\\) length \\(\\times\\) width. The area of this piece, therefore, is 2,100 m.\nAdd them together to get a net displacement of 2,700 m.\nTake two points on the velocity line. Say, t = 5 s and t = 25 s. At t = 5 s, the value of v = 40 m/s.\nAt t = 25 s, v = 140 m/s.\nFind the slope. \\(\\begin{aligned} \\mathbf{a} = \\frac{\\Delta \\mathbf{v}}{\\Delta t} \\\\ = \\frac{100\\,\\text{m/s}}{20\\,\\text{s}} \\\\ = 5{\\text{m/s}}^{2} \\end{aligned}\\)\nThe instantaneous velocity at t = 5 s, as we found in part (b) is just 40 m/s.\nFind the net displacement, which we found in part (a) was 2,700 m.\nFind the total time which for this case is 30 s.\nDivide 2,700 m/30 s = 90 m/s.","solutionImages":[],"solutionTables":[],"discussion":"The average velocity we calculated here makes sense if we look at the graph. 100m/s falls about halfway across the graph and since it is a straight line, we would expect about half the velocity to be above and half below."},{"uid":"hsphys.ch02.sec04.ex02","number":"2.4.2","title":"Using Curvy Velocity Graph to Calculate Some Stuff: Jet Car, Take Two","problem":"Use Figure 2.4 to (a) find the approximate displacement of the jet car over the time shown, (b) calculate the instantaneous acceleration at t = 30 s, (c) find the instantaneous velocity at 30 s, and (d) calculate the approximate average velocity over the interval shown.","problemImages":[],"strategy":"Because this graph is an undefined curve, we have to estimate shapes over smaller intervals in order to find the areas.\nLike when we were working with a curved displacement graph, we will need to take a tangent line at the instant we are interested and use that to calculate the instantaneous acceleration.\nThe instantaneous velocity can still be read off of the graph.\nWe will find the average velocity the same way we did in the previous example.","solution":"This problem is more complicated than the last example. To get a good estimate, we should probably break the curve into four sections. 0 → 10 s, 10 → 20 s, 20 → 40 s, and 40 → 70 s.\nCalculate the bottom rectangle (common to all pieces). 165 m/s \\(\\times\\) 70 s = 11,550 m.\nEstimate a triangle at the top, and calculate the area for each section. Section 1 contributes a triangle of width 10 s and height (210 – 165) m/s = 45 m/s so the added areas for Section 1 = (1/2)(45 m/s)(10 s) = 225 m; section 2 contributes a rectangle and a triangle with area = 100 m + 450 m = 550 m; section 3 = 150 m + 1,300 m = 1,450 m; section 4 = 2,550 m.\nAdd them together to get a net displacement of 16,325 m.\nUsing the tangent line given, we find that the slope is 1 m/s 2 .\nThe instantaneous velocity at t = 30 s, is 240 m/s.\nFind the net displacement, which we found in part (a), was 16,325 m.\nFind the total time, which for this case is 70 s.\nDivide \\(\\frac{16,325\\,\\text{m}}{70\\,\\text{s}}∼233\\,\\text{m/s}\\)","solutionImages":[],"solutionTables":[],"discussion":"This is a much more complicated process than the first problem. If we were to use these estimates to come up with the average velocity over just the first 30 s we would get about 191 m/s. By approximating that curve with a line, we get an average velocity of 202.5 m/s. Depending on our purposes and how precise an answer we need, sometimes calling a curve a straight line is a worthwhile approximation."}],"snapLabs":[{"uid":"hsphys.ch02.sec04.lab01","title":"Graphing Motion, Take Two","text":"In this activity, you will graph a moving ball’s velocity vs. time.\nyour graph from the earlier Graphing Motion Snap Lab!\n1 piece of graph paper\n1 pencil\nProcedure\nTake your graph from the earlier Graphing Motion Snap Lab! and use it to create a graph of velocity vs. time.\nUse your graph to calculate the displacement.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch02.sec04.feat01","type":"tip","title":"Tips for Success","text":"It is common in physics, especially at the early learning stages, for certain things to be neglected , as we see here. This is because it makes the concept clearer or the calculation easier. Practicing physicists use these kinds of short-cuts, as well. It works out because usually the thing being neglected is small enough that it does not significantly affect the answer. In the earlier example, the amount of time it takes the car to speed up and reach its cruising velocity is very small compared to the total time traveled.","images":[]},{"uid":"hsphys.ch02.sec04.feat02","type":"tip","title":"Tips for Success","text":"You can treat units just like you treat numbers, so a km/km=1 (or, we say, it cancels out). This is good because it can tell us whether or not we have calculated everything with the correct units. For instance, if we end up with m × s for velocity instead of m/s, we know that something has gone wrong, and we need to check our math. This process is called dimensional analysis, and it is one of the best ways to check if your math makes sense in physics.","images":[]},{"uid":"hsphys.ch02.sec04.feat03","type":"tip","title":"Tips for Success","text":"You can have negative position, velocity, and acceleration on a graph that describes the way the object is moving. You should never see a graph with negative time on an axis. Why?","images":[]}],"summaryPoints":["The slope of a velocity vs. time graph is the acceleration.","The area under a velocity vs. time curve is the displacement.","Average velocity can be found in a velocity vs. time graph by taking the weighted average of all the velocities."],"glossary":[{"term":"acceleration","termVi":"Gia tốc (a)","ipa":"/əkˌsel.əˈreɪ.ʃən/","definition":"the rate at which velocity changes","definitionVi":"Độ biến thiên vận tốc trong một đơn vị thời gian: a = Δv / Δt (đơn vị SI: m/s²).","memoryTipVi":"Vật đổi tốc độ HOẶC đổi hướng chuyển động đều có gia tốc!"}],"assessments":[{"uid":"hsphys.ch02.sec04.q003","sourceId":"fs-id1167066069168","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Consider the velocity vs. time graph shown below of a person in an elevator. Suppose the elevator is initially at rest. It then speeds up for 3 seconds, maintains that velocity for 15 seconds, then slows down for 5 seconds until it stops. Find the instantaneous velocity at t = 10 s and t = 23 s.","images":[{"sourceId":"fs-id1169832910346","filename":"CNX_HSPhysics_02_04_ve.jpg","relativePath":"media/CNX_HSPhysics_02_04_ve.jpg","alt":"The image shows a graph titled 'Velocity vs. Time' with velocity on the y-axis and time on the x-axis. The graphed line shows that velocity increases rapidly in 3 seconds to 3 m/s velocity but plateaus before losing velocity at 23 seconds."}],"choices":[{"label":"a","text":"Instantaneous velocity at t = 10 s and t = 23 s are 0 m/s and 0 m/s."},{"label":"b","text":"Instantaneous velocity at t = 10 s and t = 23 s are 0 m/s and 3 m/s."},{"label":"c","text":"Instantaneous velocity at t = 10 s and t = 23 s are 3 m/s and 0 m/s."},{"label":"d","text":"Instantaneous velocity at t = 10 s and t = 23 s are 3 m/s and 1.5 m/s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q004","sourceId":"fs-id1167065854993","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Calculate the net displacement and the average velocity of the elevator over the time interval shown.","images":[{"sourceId":"fs-id1169831643166","filename":"CNX_HSPhysics_02_04_ve.jpg","relativePath":"media/CNX_HSPhysics_02_04_ve.jpg","alt":"The image shows a graph titled 'Velocity vs. Time' with velocity on the y-axis and time on the x-axis. The graphed line shows that velocity increases rapidly in 3 seconds to 3 m/s velocity but plateaus before losing velocity at 23 seconds."}],"choices":[{"label":"a","text":"Net displacement is 45 m and average velocity is 2.10 m/s."},{"label":"b","text":"Net displacement is 45 m and average velocity is 2.28 m/s."},{"label":"c","text":"Net displacement is 57 m and average velocity is 2.66 m/s."},{"label":"d","text":"Net displacement is 57 m and average velocity is 2.48 m/s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q006","sourceId":"fs-id1167066056614","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A graph of velocity vs. time of a ship coming into a harbor is shown.\nDescribe the acceleration of the ship based on the graph.","images":[{"sourceId":"graphy","filename":"TEA_HSPhysics_02 ML_SR-14ae.jpg","relativePath":"media/TEA_HSPhysics_02 ML_SR-14ae.jpg","alt":"The image shows a simple graph with velocity on the y-axis and time on the x-axis. The graphed line trends downward from left to right."}],"choices":[{"label":"a","text":"The ship is moving in the forward direction at a steady rate. Then it accelerates in the forward direction and then decelerates."},{"label":"b","text":"The ship is moving in the forward direction at a steady rate. Then it turns around and starts decelerating, while traveling in the reverse direction. It then accelerates, but slowly."},{"label":"c","text":"The ship is moving in the forward direction at a steady rate. Then it decelerates in the forward direction, and then continues to slow down in the forward direction, but with more deceleration."},{"label":"d","text":"The ship is moving in the forward direction at a steady rate. Then it decelerates in the forward direction, and then continues to slow down in the forward direction, but with less deceleration."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q007","sourceId":"fs-id1167065926855","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Identify the time, or times, at which the instantaneous velocity is greatest, and the time, or times, at which it is negative. A sketch of velocity vs. time derived from the figure will aid in arriving at the correct answers.","images":[{"sourceId":"fs-id1164567036428","filename":"CNX_HSPhysics_02_04_pos_vs_time.jpg","relativePath":"media/CNX_HSPhysics_02_04_pos_vs_time.jpg","alt":"A graph plots time t on the x axis and position x on the y axis. The graph resembles a sine wave, beginning by going downward, then gradually sloping upward, then slightly downward, and more upward again. Points along the line are labeled a, b, c, d, e, f, g, h, I, j, k, and l."}],"choices":[{"label":"a","text":"The instantaneous velocity is greatest at f , and it is negative at d , h , I , j , and k ."},{"label":"b","text":"The instantaneous velocity is greatest at e , and it is negative at a , b , and f ."},{"label":"c","text":"The instantaneous velocity is greatest at f , and it is negative at d , h , I , j , and k"},{"label":"d","text":"The instantaneous velocity is greatest at d , and it is negative at a , b , and f ."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q008","sourceId":"fs-id1167066069168","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Consider the velocity vs. time graph shown below of a person in an elevator. Suppose the elevator is initially at rest. It then speeds up for 3 seconds, maintains that velocity for 15 seconds, then slows down for 5 seconds until it stops. Find the instantaneous velocity at t = 10 s and t = 23 s.","images":[{"sourceId":"fs-id1169832910346","filename":"CNX_HSPhysics_02_04_ve.jpg","relativePath":"media/CNX_HSPhysics_02_04_ve.jpg","alt":"The image shows a graph titled 'Velocity vs. Time' with velocity on the y-axis and time on the x-axis. The graphed line shows that velocity increases rapidly in 3 seconds to 3 m/s velocity but plateaus before losing velocity at 23 seconds."}],"choices":[{"label":"a","text":"Instantaneous velocity at t = 10 s and t = 23 s are 0 m/s and 0 m/s."},{"label":"b","text":"Instantaneous velocity at t = 10 s and t = 23 s are 0 m/s and 3 m/s."},{"label":"c","text":"Instantaneous velocity at t = 10 s and t = 23 s are 3 m/s and 0 m/s."},{"label":"d","text":"Instantaneous velocity at t = 10 s and t = 23 s are 3 m/s and 1.5 m/s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q009","sourceId":"fs-id1167065854993","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Calculate the net displacement and the average velocity of the elevator over the time interval shown.","images":[{"sourceId":"fs-id1169831643166","filename":"CNX_HSPhysics_02_04_ve.jpg","relativePath":"media/CNX_HSPhysics_02_04_ve.jpg","alt":"The image shows a graph titled 'Velocity vs. Time' with velocity on the y-axis and time on the x-axis. The graphed line shows that velocity increases rapidly in 3 seconds to 3 m/s velocity but plateaus before losing velocity at 23 seconds."}],"choices":[{"label":"a","text":"Net displacement is 45 m and average velocity is 2.10 m/s."},{"label":"b","text":"Net displacement is 45 m and average velocity is 2.28 m/s."},{"label":"c","text":"Net displacement is 57 m and average velocity is 2.66 m/s."},{"label":"d","text":"Net displacement is 57 m and average velocity is 2.48 m/s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q011","sourceId":"fs-id1163727017481","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"You are characterizing the motion of an object by measuring the location of the object at discrete moments in time. What is the minimum number of data points you would need to estimate the average acceleration of the object?","images":[],"choices":[{"label":"a","text":"1"},{"label":"b","text":"2"},{"label":"c","text":"3"},{"label":"d","text":"4"}],"hasOfficialSolution":true,"solution":"The correct answer is (c). A single point tells you only the object’s location at a particular time. Two points allow calculation of the average speed during that time interval, but do not provide information about the acceleration. Three data points are sufficient to provide information on the average acceleration, since they allow determination of average velocities for two different intervals in time."},{"uid":"hsphys.ch02.sec04.q012","sourceId":"fs-id1167065874716","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Which option best describes the average acceleration from 40 to 70 s?","images":[{"sourceId":"fs-id1169833140253","filename":"CNX_HSPhysics_02_04_flat_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_flat_img.jpg","alt":"A graph titled velocity vs. time plots time (s) on the x axis and velocity (m/s) on the y-axis. The line begins around 160 meters per second and approaches 250 meters per second as the time approaches 60 seconds."}],"choices":[{"label":"a","text":"It is negative and smaller in magnitude than the initial acceleration."},{"label":"b","text":"It is negative and larger in magnitude than the initial acceleration."},{"label":"c","text":"It is positive and smaller in magnitude than the initial acceleration."},{"label":"d","text":"It is positive and larger in magnitude than the initial acceleration."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q013","sourceId":"fs-id1167065879719","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The graph shows velocity vs. time.\nCalculate the net displacement using seven different divisions. Calculate it again using two divisions: 0 → 40 s and 40 → 70 s . Compare. Using both, calculate the average velocity.","images":[{"sourceId":"fs-id1164566987507","filename":"CNX_HSPhysics_02_04_flat_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_flat_img.jpg","alt":"A graph titled velocity vs. time plots time (s) on the x axis and velocity (m/s) on the y-axis. The line begins around 160 meters per second and approaches 250 meters per second as the time approaches 60 seconds."}],"choices":[{"label":"a","text":"Displacement and average velocity using seven divisions are 14,312.5 m and 204.5 m/s while with two divisions are 15,500 m and 221.4 m/s respectively."},{"label":"b","text":"Displacement and average velocity using seven divisions are 15,500 m and 221.4 m/s while with two divisions are 14,312.5 m and 204.5 m/s respectively."},{"label":"c","text":"Displacement and average velocity using seven divisions are 15,500 m and 204.5 m/s while with two divisions are 14,312.5 m and 221.4 m/s respectively."},{"label":"d","text":"Displacement and average velocity using seven divisions are 14,312.5 m and 221.4 m/s while with two divisions are 15,500 m and 204.5 m/s respectively."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q016","sourceId":"fs-id1167065947259","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What would the velocity vs. time graph of the object whose position is shown in the graph look like?","images":[{"sourceId":"fs-id1169832876953","filename":"CNX_HSPhysics_02_04_pos_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_pos_img.jpg","alt":"The image shows a graph titled 'Position vs Time' with position (m) on the y-axis and time (s) on the x-axis. The graphed data points show a trending curve upward from left to right."}],"choices":[{"label":"a","text":"It is a straight line with negative slope."},{"label":"b","text":"It is a straight line with positive slope."},{"label":"c","text":"It is a horizontal line at some negative value."},{"label":"d","text":"It is a horizontal line at some positive value."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q017","sourceId":"fs-id1167062339456","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which statement correctly describes the object’s speed, as well as what a graph of acceleration vs. time would look like?","images":[{"sourceId":"fs-id1169829453924","filename":"CNX_HSPhysics_02_04_vel_t_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_vel_t_img.jpg","alt":"A graph titled velocity vs. time plots time (s) on the x axis and velocity (m/s) on the y-axis. At time zero, the velocity is about 15 meters per second. The line extends at a constant rate and reaches a velocity of 170 at a time of 30 seconds."}],"choices":[{"label":"a","text":"The object is not speeding up, and the acceleration vs. time graph is a horizontal line at some negative value."},{"label":"b","text":"The object is not speeding up, and the acceleration vs. time graph is a horizontal line at some positive value."},{"label":"c","text":"The object is speeding up, and the acceleration vs. time graph is a horizontal line at some negative value."},{"label":"d","text":"The object is speeding up, and the acceleration vs. time graph is a horizontal line at some positive value."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q018","sourceId":"fs-id1167065894206","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Calculate that object’s net displacement over the time shown.","images":[{"sourceId":"fs-id1164567912619","filename":"CNX_HSPhysics_02_04_vel_t_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_vel_t_img.jpg","alt":"A graph titled velocity vs. time plots time (s) on the x axis and velocity (m/s) on the y-axis. At time zero, the velocity is about 15 meters per second. The line extends at a constant rate and reaches a velocity of 170 at a time of 30 seconds."}],"choices":[{"label":"a","text":"540 m"},{"label":"b","text":"2,520 m"},{"label":"c","text":"2,790 m"},{"label":"d","text":"5,040 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q019","sourceId":"fs-id1167066104876","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the object’s average velocity?","images":[{"sourceId":"eip-idm657774256","filename":"CNX_HSPhysics_02_04_vel_t_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_vel_t_img.jpg","alt":"A graph titled velocity vs. time plots time (s) on the x axis and velocity (m/s) on the y-axis. At time zero, the velocity is about 15 meters per second. The line extends at a constant rate and reaches a velocity of 170 at a time of 30 seconds."}],"choices":[{"label":"a","text":"18 m/s"},{"label":"b","text":"84 m/s"},{"label":"c","text":"93 m/s"},{"label":"d","text":"168 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q020","sourceId":"fs-id1167065872640","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Consider the motion of the object whose velocity is charted in the graph.\nDuring which points is the object slowing down and speeding up?","images":[{"sourceId":"fs-id1164565471831","filename":"CNX_HSPhysics_02_04_v_t_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_v_t_img.jpg","alt":"A graph plots time t on the x axis and velocity v on the y axis. The line extends from the origin upward and to the right and plots points a, b, c, and d. At point d, the line begins to slope downward to point e. At point e, the line then begins to slope gradually upward through points f, g, and h, then drops off sharply through points I, j, k, and land on point l on the x axis again."}],"choices":[{"label":"a","text":"It is slowing down between d and e . It is speeding up between a and d and e and h"},{"label":"b","text":"It is slowing down between a and d and e and h . It is speeding up between d and e and then after i ."},{"label":"c","text":"It is slowing down between d and e and then after h . It is speeding up between a and d and e and h ."},{"label":"d","text":"It is slowing down between a and d and e and h . It is speeding up between d and e and then after i ."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch02.sec04.q021","sourceId":"fs-id1167066021140","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Divide the graph into approximate sections, and use those sections to graph the velocity vs. time of the object.\nThen calculate the acceleration during each section, and calculate the approximate average velocity.","images":[{"sourceId":"end","filename":"CNX_HSPhysics_02_04_pvst_img.jpg","relativePath":"media/CNX_HSPhysics_02_04_pvst_img.jpg","alt":"A graph titled 'position vs time' with position (m) on the y-axis and time (s) on the x-axis. The data points trend upward for the first 5 seconds before moving downward by 10 seconds. After 10 seconds, the points gently curve upward with a max position of 25 m at 20 seconds."}],"choices":[{"label":"a","text":"Acceleration is zero and average velocity is 1.25 m/s."},{"label":"b","text":"Acceleration is constant with some positive value and average velocity is 1.25 m/s."},{"label":"c","text":"Acceleration is zero and average velocity is 0.25 m/s."},{"label":"d","text":"Acceleration is constant with some positive value and average velocity is 0.25 m/s."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":2,"subsectionCount":3,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":1,"assessmentCount":15}}],"summary":{"totalSections":5,"totalKeyEquations":6,"totalWorkedExamples":9,"totalSnapLabs":4,"totalGlossaryTerms":18,"totalAssessments":49,"referencedMediaCount":35},"qualityGate":{"passed":true,"checkedUids":75,"errors":[],"warnings":[]}};
